(window.__X=window.__X||{})["xwork"]={"v":1,"lessons":[{"id":"email","en":"The structure of a work email","th":"โครงสร้างอีเมลงาน","intro":"อีเมลงานที่ดีมี 6 ส่วน: subject, greeting, opening, body, closing และ sign-off ผู้อ่านควรรู้ภายใน 10 วินาทีว่าเรื่องอะไรและต้องทำอะไร","r":[],"tips":[],"items":[{"id":"wk-email-0","p":0,"s":"หัวเรื่องอีเมลใดดีที่สุด?","gap":0,"o":{"A":"Important!!!","B":"Hello","C":"Question","D":"Request: test report for PO 4512"},"oth":{},"a":"D","x":"บอกการกระทำ (Request) และเรื่อง (test report, PO 4512) ชัดเจน","v":[]},{"id":"wk-email-1","p":0,"s":"ไม่รู้ชื่อผู้รับ ควรขึ้นต้นอย่างไร?","gap":0,"o":{"A":"To you,","B":"Hey,","C":"Dear Sir or Madam,","D":"Hi guys,"},"oth":{},"a":"C","x":"แบบทางการเมื่อไม่ทราบชื่อ","v":[]},{"id":"wk-email-2","p":0,"s":"ประโยคเปิดใดบอกจุดประสงค์ชัดที่สุด?","gap":0,"o":{"A":"How are you? I hope everything is fine and the weather is good.","B":"Please read this email.","C":"I have something.","D":"I am writing to confirm the delivery date."},"oth":{},"a":"D","x":"ประโยคแรกควรบอกจุดประสงค์ทันที","v":[]},{"id":"wk-email-3","p":0,"s":"คำลงท้ายใดเหมาะกับอีเมลงานทั่วไป?","gap":0,"o":{"A":"Love,","B":"Bye bye","C":"Best regards,","D":"See ya"},"oth":{},"a":"C","x":"Best regards / Kind regards ใช้ได้กับงานทั่วไป","v":[]},{"id":"wk-email-4","p":0,"s":"ถ้าอีเมลมีหลายเรื่อง ควรเขียนอย่างไร?","gap":0,"o":{"A":"เขียนเป็นย่อหน้ายาวย่อหน้าเดียว","B":"ส่งไฟล์แนบอย่างเดียว","C":"ไม่ต้องเขียนหัวเรื่อง","D":"แยกเป็นข้อหรือย่อหน้าสั้น"},"oth":{},"a":"D","x":"bullet points ทำให้อ่านเร็วและไม่พลาด","v":[]},{"id":"wk-email-5","p":0,"s":"หลัง \"Dear Mr. Lee\" ควรใส่เครื่องหมายใด?","gap":0,"o":{"A":"full stop (.)","B":"ไม่ต้องใส่อะไร (แบบไทย)","C":"question mark (?)","D":"comma (,)"},"oth":{},"a":"D","x":"อีเมลภาษาอังกฤษแบบสากลใช้ Dear Mr. Lee, (อเมริกันแบบทางการอาจใช้ :)","v":[]},{"id":"wk-email-6","p":0,"s":"ส่วนใดควรบอก \"สิ่งที่ต้องการให้ผู้อ่านทำต่อ\"?","gap":0,"o":{"A":"greeting","B":"subject เท่านั้น","C":"closing","D":"signature"},"oth":{},"a":"C","x":"closing เช่น Could you reply by Friday?","v":[]},{"id":"wk-email-7","p":0,"s":"ข้อใดเป็น signature ที่ครบ?","gap":0,"o":{"A":"ชื่อเล่นอย่างเดียว","B":"รูปภาพอย่างเดียว","C":"ชื่อ ตำแหน่ง บริษัท เบอร์โทร","D":"ไม่ต้องมี"},"oth":{},"a":"C","x":"ผู้รับจะรู้ว่าติดต่อใครและอย่างไร","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">อีเมลงานเหมือน <b>ซองจดหมายที่มีหน้าต่าง</b>: subject คือหน้าต่างที่ผู้อ่านเห็นก่อนเปิด ประโยคแรกคือหัวใจ ถ้าผู้อ่านอ่านแค่สองบรรทัดแรก ก็ต้องรู้ว่าเรื่องอะไรและต้องทำอะไร</div><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">Subject: Request: test report for PO 4512</div><div class=\"wd-r\"><span class=\"wd-l\">Greeting</span><div class=\"wd-t\" lang=\"en\">Dear Ms. Wong,</div></div><div class=\"wd-r\"><span class=\"wd-l\">Opening</span><div class=\"wd-t\" lang=\"en\">I am writing to request the test report for PO 4512.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Body</span><div class=\"wd-t\" lang=\"en\">We need the report to release the shipment. Please include:<br>• insulation resistance results<br>• sample size and date</div></div><div class=\"wd-r\"><span class=\"wd-l\">Closing</span><div class=\"wd-t\" lang=\"en\">Could you send it by Friday, 15 November? Please let me know if you need any information.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Sign-off</span><div class=\"wd-t\" lang=\"en\">Best regards,<br>Pop<br>Quality Engineer | ABC Electronics | +66 2 123 4567</div></div></div><figcaption>หกส่วนของอีเมลงาน</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>Subject: การกระทำ + เรื่อง</li><li>Greeting: Dear / Hi + ชื่อ</li><li>Opening: จุดประสงค์ในประโยคเดียว</li><li>Body: รายละเอียดสั้นๆ เป็นข้อ</li><li>Closing: ต้องการอะไร เมื่อไร</li><li>Sign-off: Best regards + ชื่อ ตำแหน่ง</li></ol><figcaption>ลำดับการเขียน</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">Subject</div><div class=\"tf-value\">Action: topic + reference no.</div></div><div class=\"tense-formula\"><div class=\"tf-label\">Opening</div><div class=\"tf-value\">I am writing to + verb ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">Closing</div><div class=\"tf-value\">Could you ... by + date?</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>Subject: สั้นและบอกเรื่อง</b> — ใส่คำสำคัญและการกระทำ เช่น Request: test report for PO 4512 · Delay: shipment on 12 Nov</p><p><b>Greeting</b> — Dear Mr. Lee, (ทางการ) · Hi Anna, (คุ้นเคย) · Dear Sir or Madam, (ไม่รู้ชื่อ) ใช้ comma ท้ายคำทักทาย</p><p><b>Opening + Body</b> — ประโยคแรกบอกจุดประสงค์ทันที แล้วให้รายละเอียดเป็นย่อหน้าสั้นหรือ bullet points<br><span class=\"bv-rx\">I am writing to request the test report for PO 4512. <small>ขอเรียนเพื่อขอรายงานผลทดสอบของใบสั่งซื้อ 4512</small></span></p><p><b>Closing + Sign-off</b> — บอกสิ่งที่ต้องการต่อ + คำลงท้าย: Best regards, / Kind regards, / Sincerely, แล้วตามด้วยชื่อ ตำแหน่ง บริษัท<br><span class=\"bv-rx\">Please let me know if you have any questions. <small>หากมีคำถามโปรดแจ้ง</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I am writing to confirm our meeting on Tuesday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I am writing to confirm our meeting on Tuesday.</div><div class=\"ex-th thai\">ขอเรียนเพื่อยืนยันการประชุมวันอังคาร</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please find the report attached.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please find the report attached.</div><div class=\"ex-th thai\">รายงานแนบมาด้วย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Could you reply by Thursday?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Could you reply by Thursday?</div><div class=\"ex-th thai\">ช่วยตอบกลับภายในวันพฤหัสได้ไหม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Thank you for your quick response.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Thank you for your quick response.</div><div class=\"ex-th thai\">ขอบคุณที่ตอบกลับอย่างรวดเร็ว</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Subject: (ว่าง)</p><p class=\"ok\">✓ Subject: Delay: shipment for PO 4512</p><small>อีเมลไม่มีหัวเรื่องมักถูกเปิดช้าหรือหลุดไปในกล่องสแปม</small></div><div class=\"bv-m\"><p class=\"no\">✗ Dear Pop Sir,</p><p class=\"ok\">✓ Dear Mr. Pop, / Dear Pop,</p><small>ไม่ใช้ Sir ต่อท้ายชื่อ</small></div><div class=\"bv-m\"><p class=\"no\">✗ ย่อหน้าแรกเล่าเรื่องยาวก่อนบอกจุดประสงค์</p><p class=\"ok\">✓ บอกจุดประสงค์ในประโยคแรก</p><small>ผู้อ่านที่ยุ่งอาจอ่านแค่ต้นอีเมล</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ก่อนกดส่ง ตรวจ 3 อย่าง: หัวเรื่องบอกเรื่องชัด, ประโยคแรกบอกจุดประสงค์, ท้ายอีเมลบอกว่าต้องการอะไรเมื่อไร</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Subject: Request: updated drawing for part 7731. Dear Mr. Chen, I am writing to request the updated drawing. Could you send it by Monday? Best regards, Pop\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Subject: Request: updated drawing for part 7731.</mark> Dear Mr. Chen, <mark>I am writing to request</mark> the updated drawing. <mark>Could you send it by</mark> Monday? <mark>Best regards</mark>, Pop</div><div class=\"ts-th\">หัวเรื่อง: ขอแบบฉบับแก้ไขของชิ้นส่วน 7731 เรียนคุณเฉิน ขอเรียนเพื่อขอแบบฉบับแก้ไข ช่วยส่งภายในวันจันทร์ได้ไหม ขอแสดงความนับถือ ป๊อป</div></div></div></div>","easy":{"say":"อีเมลงานมี 6 ส่วน และประโยคแรกต้องบอกจุดประสงค์ทันที ผู้อ่านที่ยุ่งควรรู้เรื่องภายในสองบรรทัด","eg":["<b>I am writing to request</b> the test report.","ขอเรียนเพื่อขอรายงานผลทดสอบ"],"rule":"Subject ชัด → ประโยคแรกบอกจุดประสงค์ → ปิดด้วยสิ่งที่ต้องการ + วันที่"}},{"id":"phrase","en":"Useful email phrases","th":"วลีอีเมลที่ใช้บ่อย","intro":"วลีสำเร็จรูปช่วยให้เขียนอีเมลได้เร็วและเป็นธรรมชาติ จำเป็นชุดตามหน้าที่: เปิด แนบไฟล์ ขอ ยืนยัน และปิด","r":[],"tips":[],"items":[{"id":"wk-phrase-0","p":0,"s":"Please find _____ the invoice for October.","gap":1,"o":{"A":"attached","B":"attaching","C":"attach","D":"attachment"},"oth":{},"a":"A","x":"Please find attached = กรุณาดูไฟล์แนบ","v":[]},{"id":"wk-phrase-1","p":0,"s":"I look forward to _____ from you.","gap":1,"o":{"A":"heard","B":"be heard","C":"hearing","D":"hear"},"oth":{},"a":"C","x":"look forward to + V-ing","v":[]},{"id":"wk-phrase-2","p":0,"s":"_____ your email of 3 March, the order has been shipped.","gap":1,"o":{"A":"Regards","B":"Regard","C":"Regarded","D":"Regarding"},"oth":{},"a":"D","x":"Regarding = เกี่ยวกับ","v":[]},{"id":"wk-phrase-3","p":0,"s":"I would appreciate it if you _____ send the file today.","gap":1,"o":{"A":"are","B":"will be","C":"can to","D":"could"},"oth":{},"a":"D","x":"I would appreciate it if you could ... (สุภาพมาก)","v":[]},{"id":"wk-phrase-4","p":0,"s":"_____ our phone call, I am sending the price list.","gap":1,"o":{"A":"To follow","B":"Follow","C":"Following","D":"Followed"},"oth":{},"a":"C","x":"Following = หลังจาก / ตามที่","v":[]},{"id":"wk-phrase-5","p":0,"s":"I can _____ that the parts were delivered.","gap":1,"o":{"A":"confirmed to","B":"confirming","C":"confirmation","D":"confirm"},"oth":{},"a":"D","x":"I can confirm that ... = ขอยืนยันว่า","v":[]},{"id":"wk-phrase-6","p":0,"s":"ประโยคใดใช้ปิดอีเมลได้?","gap":0,"o":{"A":"Please let me know if you have any questions.","B":"Regarding your email,","C":"I am writing to","D":"Please find attached"},"oth":{},"a":"A","x":"เป็นประโยคปิดที่ใช้บ่อย","v":[]},{"id":"wk-phrase-7","p":0,"s":"\"Thank you in advance\" หมายถึงอะไร?","gap":0,"o":{"A":"ไม่ต้องขอบคุณ","B":"ขอบคุณล่วงหน้า","C":"ขอบคุณมากที่สุด","D":"ขอบคุณย้อนหลัง"},"oth":{},"a":"B","x":"ใช้เมื่อขอให้ทำบางอย่าง","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">วลีอีเมลเหมือน <b>บล็อกสำเร็จรูป</b> ในงานก่อสร้าง ไม่ต้องหล่อใหม่ทุกครั้ง หยิบบล็อกที่ใช่มาวางต่อกัน ได้อีเมลที่ถูกต้องและสุภาพในเวลาไม่กี่นาที</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>หน้าที่</th><th>วลี</th></tr></thead><tbody><tr><td>เปิด</td><td>I am writing to ... / Regarding ... / Following our call, ...</td></tr><tr><td>แนบไฟล์</td><td>Please find attached ... / I have attached ...</td></tr><tr><td>ขอ</td><td>Could you please ...? / I would appreciate it if you could ...</td></tr><tr><td>ยืนยัน</td><td>I can confirm that ... / Please confirm ...</td></tr><tr><td>ขอบคุณ</td><td>Thank you for ... / Thank you in advance.</td></tr><tr><td>ปิด</td><td>Please let me know if ... / I look forward to hearing from you.</td></tr></tbody></table></div><figcaption>บล็อกสำเร็จรูปของอีเมล</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">look forward to</div><div class=\"tf-value\">+ V-ing</div></div><div class=\"tense-formula\"><div class=\"tf-label\">Please find attached</div><div class=\"tf-value\">+ สิ่งที่แนบ</div></div><div class=\"tense-formula\"><div class=\"tf-label\">I would appreciate it if you could</div><div class=\"tf-value\">+ V1</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>เปิดเรื่อง</b> — I am writing to ... · Regarding your email of 5 May, ... · Thank you for your email about ... · Following our call, ...</p><p><b>แนบไฟล์และอ้างอิง</b> — Please find attached ... · I have attached ... · As discussed, ... · Please see the table below.</p><p><b>ขอและยืนยัน</b> — Could you please ...? · I would appreciate it if you could ... · I can confirm that ... · Please confirm ...</p><p><b>ปิด</b> — Please let me know if you have any questions. · I look forward to hearing from you. · Thank you in advance.</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please find attached the updated schedule.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please find attached the updated schedule.</div><div class=\"ex-th thai\">กรุณาดูตารางฉบับแก้ไขในไฟล์แนบ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Following our meeting, here are the action items.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Following our meeting, here are the action items.</div><div class=\"ex-th thai\">ตามที่ประชุมกัน นี่คือรายการงาน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I would appreciate it if you could reply today.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I would appreciate it if you could reply today.</div><div class=\"ex-th thai\">จะขอบคุณมากถ้าตอบกลับวันนี้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I look forward to working with you.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I look forward to working with you.</div><div class=\"ex-th thai\">ยินดีที่จะได้ร่วมงานกับคุณ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ I look forward to hear from you.</p><p class=\"ok\">✓ I look forward to hearing from you.</p><small>to เป็นบุพบท ตามด้วย V-ing</small></div><div class=\"bv-m\"><p class=\"no\">✗ Please find the attach file.</p><p class=\"ok\">✓ Please find the attached file.</p><small>ใช้ attached (V3) เป็นคุณศัพท์</small></div><div class=\"bv-m\"><p class=\"no\">✗ Regards your email, ...</p><p class=\"ok\">✓ Regarding your email, ...</p><small>Regards ใช้เป็นคำลงท้าย / Regarding = เกี่ยวกับ</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> อย่าใช้ &quot;Please be informed that ...&quot; บ่อยเกินไป ฟังดูแข็งและเก่า ใช้ &quot;I would like to let you know that ...&quot; หรือบอกเรื่องตรงๆ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Regarding your email of 2 May, please find attached the revised quotation. I would appreciate it if you could confirm by Friday. I look forward to hearing from you.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Regarding</mark> your email of 2 May, <mark>please find attached</mark> the revised quotation. <mark>I would appreciate it if you could</mark> confirm by Friday. <mark>I look forward to hearing from you.</mark></div><div class=\"ts-th\">เกี่ยวกับอีเมลของคุณเมื่อวันที่ 2 พฤษภาคม กรุณาดูใบเสนอราคาฉบับแก้ไขที่แนบมา จะขอบคุณมากหากยืนยันภายในวันศุกร์ หวังว่าจะได้รับคำตอบ</div></div></div></div>","easy":{"say":"วลีอีเมลคือบล็อกสำเร็จรูป จำตามหน้าที่: เปิด แนบ ขอ ยืนยัน ปิด แล้วหยิบมาต่อกัน","eg":["<b>Please find attached</b> ... · <b>I look forward to hearing</b> from you.","กรุณาดูไฟล์แนบ · หวังว่าจะได้รับคำตอบ"],"rule":"look forward to + V-ing"}},{"id":"tone","en":"Polite tone and formality","th":"ความสุภาพและระดับภาษา","intro":"ภาษาอังกฤษในงานใช้ \"ความสุภาพแบบอ้อม\" แทนคำสั่งตรงๆ และเลือกระดับภาษาให้เหมาะกับผู้รับ","r":[],"tips":[],"items":[{"id":"wk-tone-0","p":0,"s":"ประโยคใดสุภาพที่สุด?","gap":0,"o":{"A":"Check the file.","B":"Check the file now!","C":"You must check the file.","D":"Would you mind checking the file?"},"oth":{},"a":"D","x":"Would you mind + V-ing ... ? สุภาพที่สุด","v":[]},{"id":"wk-tone-1","p":0,"s":"Would you mind _____ the window?","gap":1,"o":{"A":"close","B":"closed","C":"closing","D":"to close"},"oth":{},"a":"C","x":"Would you mind + V-ing","v":[]},{"id":"wk-tone-2","p":0,"s":"คำใดเป็นภาษาทางการของ \"help\"?","gap":0,"o":{"A":"buy","B":"tell","C":"get","D":"assist"},"oth":{},"a":"D","x":"assist เป็นคำทางการ","v":[]},{"id":"wk-tone-3","p":0,"s":"วิธีบอกข่าวร้ายอย่างสุภาพคือข้อใด?","gap":0,"o":{"A":"I'm afraid the shipment will be late.","B":"The shipment is late. Deal with it.","C":"Late shipment.","D":"You will wait."},"oth":{},"a":"A","x":"I'm afraid ... ทำให้ข่าวร้ายนุ่มลง","v":[]},{"id":"wk-tone-4","p":0,"s":"ควรใช้ประโยคใดแทน \"You are wrong.\"?","gap":0,"o":{"A":"I think there may be a mistake in the figures.","B":"Wrong!","C":"This is your mistake.","D":"You are very wrong."},"oth":{},"a":"A","x":"บอกปัญหาโดยไม่กล่าวโทษคน","v":[]},{"id":"wk-tone-5","p":0,"s":"คำใดเป็นภาษาทางการของ \"buy\"?","gap":0,"o":{"A":"purchase","B":"pick","C":"grab","D":"get"},"oth":{},"a":"A","x":"purchase ใช้ในเอกสารจัดซื้อ (purchase order)","v":[]},{"id":"wk-tone-6","p":0,"s":"I was wondering if you _____ help me.","gap":1,"o":{"A":"can to","B":"are","C":"will","D":"could"},"oth":{},"a":"D","x":"I was wondering if you could ... สุภาพมาก","v":[]},{"id":"wk-tone-7","p":0,"s":"ทำไมควรใช้ \"by 3 p.m. today\" แทน \"ASAP\"?","gap":0,"o":{"A":"ASAP ผิดไวยากรณ์","B":"ไม่มีเหตุผล","C":"ชัดเจนกว่าและไม่ฟังดูกดดัน","D":"ASAP เป็นคำหยาบ"},"oth":{},"a":"C","x":"กำหนดเวลาจริงช่วยให้ผู้รับวางแผนได้","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ภาษาไทยใช้ \"ค่ะ/ครับ\" \"รบกวน\" \"ช่วย...หน่อย\" ภาษาอังกฤษไม่มีคำลงท้ายแบบนั้น จึงใช้ <b>รูปประโยค</b> สร้างความสุภาพแทน ยิ่งประโยคอ้อมและยาวขึ้น ยิ่งสุภาพ: Send → Could you send → Would you mind sending</div><figure class=\"bv bv-scale\"><div class=\"bv-sr\"><span class=\"bv-sw\">Send me the file.</span><span class=\"bv-sb\"><i style=\"width:10%\"></i></span><span class=\"bv-st\">คำสั่ง (ห้วน)</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">Please send me the file.</span><span class=\"bv-sb\"><i style=\"width:40%\"></i></span><span class=\"bv-st\">สุภาพพื้นฐาน</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">Could you send me the file?</span><span class=\"bv-sb\"><i style=\"width:65%\"></i></span><span class=\"bv-st\">สุภาพ (ใช้บ่อยที่สุด)</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">Would you mind sending me the file?</span><span class=\"bv-sb\"><i style=\"width:85%\"></i></span><span class=\"bv-st\">สุภาพมาก</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">I was wondering if you could send me the file.</span><span class=\"bv-sb\"><i style=\"width:100%\"></i></span><span class=\"bv-st\">สุภาพที่สุด / อ้อมที่สุด</span></div><figcaption>บันไดความสุภาพ</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ทั่วไป</th><th>ทางการ</th></tr></thead><tbody><tr><td>ask</td><td>request / inquire</td></tr><tr><td>get</td><td>receive / obtain</td></tr><tr><td>help</td><td>assist</td></tr><tr><td>tell</td><td>inform / notify</td></tr><tr><td>buy</td><td>purchase</td></tr><tr><td>need</td><td>require</td></tr><tr><td>start</td><td>commence</td></tr></tbody></table></div><figcaption>คำทางการใช้ในเอกสารและอีเมลถึงลูกค้า</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ขอแบบสุภาพ</div><div class=\"tf-value\">Could you + V1 ...?</div></div><div class=\"tense-formula\"><div class=\"tf-label\">สุภาพมาก</div><div class=\"tf-value\">Would you mind + V-ing ...?</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ข่าวร้าย</div><div class=\"tf-value\">I&#x27;m afraid / Unfortunately, ...</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ทำคำขอให้นุ่มลง</b> — Send me → Could you send me ...? → Would you mind sending ...? → I was wondering if you could ...</p><p><b>ปฏิเสธหรือบอกข่าวร้ายอย่างสุภาพ</b> — I'm afraid ... · Unfortunately, ... · We regret to inform you that ...<br><span class=\"bv-rx\">I'm afraid we cannot meet the deadline. <small>เกรงว่าเราจะทำไม่ทันกำหนด</small></span></p><p><b>ระดับภาษา</b> — ทางการ: request, receive, assist, inform, purchase / ทั่วไป: ask, get, help, tell, buy</p><p><b>หลีกเลี่ยงคำที่แรง</b> — You must → Please make sure ... · You are wrong → I think there may be a mistake ... · ASAP → by 3 p.m. today</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Could you please update the schedule?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Could you please update the schedule?</div><div class=\"ex-th thai\">ช่วยอัปเดตตารางได้ไหม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I&#x27;m afraid we are out of stock.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I&#x27;m afraid we are out of stock.</div><div class=\"ex-th thai\">เกรงว่าสินค้าหมด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We regret to inform you that the event is cancelled.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We regret to inform you that the event is cancelled.</div><div class=\"ex-th thai\">เราเสียใจที่ต้องแจ้งว่างานถูกยกเลิก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please make sure the door is locked.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please make sure the door is locked.</div><div class=\"ex-th thai\">โปรดตรวจให้แน่ใจว่าประตูล็อกแล้ว</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Please kindly do the needful.</p><p class=\"ok\">✓ Could you please handle this?</p><small>สำนวนเก่าและไม่ชัด</small></div><div class=\"bv-m\"><p class=\"no\">✗ I want the report now.</p><p class=\"ok\">✓ Could I have the report by 2 p.m.?</p><small>I want ฟังดูเป็นคำสั่ง</small></div><div class=\"bv-m\"><p class=\"no\">✗ Would you mind to send ...?</p><p class=\"ok\">✓ Would you mind sending ...?</p><small>mind + V-ing</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ภาษาทางการไม่จำเป็นต้องยาก &quot;We will start the work on Monday.&quot; ชัดกว่า &quot;The work will be commenced on Monday.&quot; ใช้คำทางการเมื่อจำเป็น แต่รักษาความชัดเจนไว้ก่อน</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Dear Ms. Park, I&#x27;m afraid the parts will arrive two days late. Would you mind moving the inspection to Thursday? We apologize for the inconvenience.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Dear Ms. Park, <mark>I&#x27;m afraid</mark> the parts will arrive two days late. <mark>Would you mind</mark> moving the inspection to Thursday? <mark>We apologize for</mark> the inconvenience.</div><div class=\"ts-th\">เรียนคุณพาร์ค เกรงว่าชิ้นส่วนจะมาถึงช้าสองวัน รบกวนเลื่อนการตรวจไปวันพฤหัสได้ไหม ขออภัยในความไม่สะดวก</div></div></div></div>","easy":{"say":"ภาษาอังกฤษไม่มี \"ค่ะ/ครับ\" จึงใช้รูปประโยคสร้างความสุภาพ ยิ่งอ้อมยิ่งสุภาพ","eg":["Send → <b>Could you</b> send → <b>Would you mind</b> sending","ส่งมา → ช่วยส่งได้ไหม → รบกวนส่งได้ไหม"],"rule":"Could you + V1 · Would you mind + V-ing · I'm afraid + ข่าวร้าย"}},{"id":"request","en":"Requests, replies and follow-ups","th":"ขอข้อมูล ตอบกลับ และติดตามงาน","intro":"อีเมลงานส่วนใหญ่คือการขอ ตอบ และติดตาม เขียนให้ชัดว่าต้องการอะไร เมื่อไร และตอบให้ครบทุกข้อที่ถูกถาม","r":[],"tips":[],"items":[{"id":"wk-request-0","p":0,"s":"ประโยคใดเป็นการติดตามงานอย่างสุภาพ?","gap":0,"o":{"A":"Reply now.","B":"I am following up on my email of 3 May.","C":"Why have you not replied?","D":"You forgot my email."},"oth":{},"a":"B","x":"อ้างอิงอีเมลเดิมโดยไม่กล่าวโทษ","v":[]},{"id":"wk-request-1","p":0,"s":"ถ้ายังไม่มีคำตอบ ควรเขียนว่าอะไร?","gap":0,"o":{"A":"I do not know.","B":"No answer.","C":"I will get back to you by Wednesday.","D":"Wait."},"oth":{},"a":"C","x":"บอกว่าจะตอบเมื่อไร","v":[]},{"id":"wk-request-2","p":0,"s":"\"I confirm receipt of your order.\" หมายถึงอะไร?","gap":0,"o":{"A":"ส่งใบเสร็จ","B":"ยกเลิกคำสั่งซื้อ","C":"ยืนยันใบเสร็จ","D":"ยืนยันว่าได้รับคำสั่งซื้อแล้ว"},"oth":{},"a":"D","x":"receipt (ในที่นี้) = การได้รับ","v":[]},{"id":"wk-request-3","p":0,"s":"คำขอที่ดีควรมีอะไรบ้าง?","gap":0,"o":{"A":"คำขอโทษยาวๆ","B":"ไฟล์แนบอย่างเดียว","C":"สิ่งที่ต้องการ เหตุผล และกำหนดเวลา","D":"เฉพาะสิ่งที่ต้องการ"},"oth":{},"a":"C","x":"ผู้รับจะเข้าใจความสำคัญและวางแผนได้","v":[]},{"id":"wk-request-4","p":0,"s":"Just a gentle _____ that the meeting starts at 9.","gap":1,"o":{"A":"remark","B":"remind","C":"reminder","D":"remember"},"oth":{},"a":"C","x":"a gentle reminder = การเตือนอย่างสุภาพ","v":[]},{"id":"wk-request-5","p":0,"s":"ตอบอีเมลที่มีคำถามหลายข้อควรทำอย่างไร?","gap":0,"o":{"A":"ตอบทีละข้อ อาจแทรกคำตอบใต้คำถาม","B":"ตอบเฉพาะข้อแรก","C":"โทรไปแทน ไม่ต้องตอบ","D":"ตอบรวมย่อหน้าเดียว"},"oth":{},"a":"A","x":"ช่วยไม่ให้ตกหล่น","v":[]},{"id":"wk-request-6","p":0,"s":"\"Noted, thank you.\" ใช้เมื่อใด?","gap":0,"o":{"A":"ขอข้อมูลเพิ่ม","B":"รับทราบข้อมูลแล้ว","C":"ยกเลิก","D":"ไม่เห็นด้วย"},"oth":{},"a":"B","x":"สั้นและสุภาพสำหรับรับทราบ","v":[]},{"id":"wk-request-7","p":0,"s":"I am writing to _____ about the delivery date.","gap":1,"o":{"A":"inquire","B":"inquired","C":"inquiring","D":"inquiry"},"oth":{},"a":"A","x":"I am writing to + V1 (inquire = สอบถาม)","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">การขอ–ตอบ–ติดตาม เหมือน <b>การส่งลูกปิงปอง</b>: ส่งลูกให้ชัด (ขออะไร เมื่อไร) รับลูกให้ครบ (ตอบทุกข้อ) ถ้าลูกหาย ตามเก็บอย่างสุภาพ (follow-up) โดยไม่โทษคู่เล่น</div><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">Subject: Follow-up: CoC for lot 25</div><div class=\"wd-r\"><span class=\"wd-l\">Opening</span><div class=\"wd-t\" lang=\"en\">Dear Mr. Tan,<br>I am following up on my email of 3 May about the CoC for lot 25.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Reason</span><div class=\"wd-t\" lang=\"en\">We need it to release the goods to our customer.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Request + deadline</span><div class=\"wd-t\" lang=\"en\">Could you send it by 3 p.m. on Friday, 10 May?</div></div><div class=\"wd-r\"><span class=\"wd-l\">Closing</span><div class=\"wd-t\" lang=\"en\">Thank you for your help.<br>Best regards,<br>Pop</div></div></div><figcaption>อีเมลติดตามที่สุภาพและชัดเจน</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ขอ</div><div class=\"tf-value\">Could you + V1 ... by + วันเวลา?</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ติดตาม</div><div class=\"tf-value\">I am following up on + อีเมลเดิม</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ยังไม่มีคำตอบ</div><div class=\"tf-value\">I will get back to you by + วัน</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ขอ (request)</b> — บอกสิ่งที่ต้องการ + เหตุผลสั้นๆ + กำหนดเวลา<br><span class=\"bv-rx\">Could you send the CoC for lot 25? We need it to release the goods by Friday. <small>ช่วยส่งใบรับรอง (CoC) ของล็อต 25 ได้ไหม เราต้องใช้เพื่อปล่อยของภายในวันศุกร์</small></span></p><p><b>ตอบ (reply)</b> — ขอบคุณ + ตอบทีละข้อ + บอกสิ่งที่ยังไม่มีและจะส่งเมื่อไร<br><span class=\"bv-rx\">Thank you for your email. Please see my answers below. <small>ขอบคุณสำหรับอีเมล กรุณาดูคำตอบด้านล่าง</small></span></p><p><b>ติดตาม (follow-up / reminder)</b> — อ้างอิงอีเมลเดิม สุภาพ ไม่กล่าวโทษ<br><span class=\"bv-rx\">I am following up on my email of 3 May about the samples. <small>ขอติดตามอีเมลวันที่ 3 พฤษภาคมเรื่องตัวอย่าง</small></span><br><span class=\"bv-rx\">Just a gentle reminder that the report is due tomorrow. <small>ขอเตือนเบาๆ ว่ารายงานครบกำหนดพรุ่งนี้</small></span></p><p><b>ยืนยันและรับทราบ</b> — Noted, thank you. · I confirm receipt of ... · I will get back to you by ...</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Could you share the latest drawing by noon?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Could you share the latest drawing by noon?</div><div class=\"ex-th thai\">ช่วยแชร์แบบล่าสุดภายในเที่ยงได้ไหม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please see my answers below in blue.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please see my answers below in blue.</div><div class=\"ex-th thai\">กรุณาดูคำตอบสีฟ้าด้านล่าง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I will check with the team and get back to you.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I will check with the team and get back to you.</div><div class=\"ex-th thai\">ฉันจะสอบถามทีมแล้วแจ้งกลับ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Just a gentle reminder about tomorrow’s audit.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Just a gentle reminder about tomorrow’s audit.</div><div class=\"ex-th thai\">ขอเตือนเรื่องการตรวจประเมินพรุ่งนี้</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Why you not reply?</p><p class=\"ok\">✓ I am following up on my previous email.</p><small>ฟังดูกล่าวโทษและผิดไวยากรณ์</small></div><div class=\"bv-m\"><p class=\"no\">✗ I will revert back to you.</p><p class=\"ok\">✓ I will get back to you.</p><small>revert back ซ้ำซ้อนและไม่เป็นธรรมชาติในภาษาสากล</small></div><div class=\"bv-m\"><p class=\"no\">✗ Please send ASAP!!!</p><p class=\"ok\">✓ Please send it by 3 p.m. today.</p><small>ใส่เวลาจริง ไม่ใช้เครื่องหมายตกใจหลายตัว</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ถ้าต้องติดตามครั้งที่สอง ให้ forward อีเมลเดิมพร้อมประโยคสั้นด้านบน ผู้รับจะเห็นเรื่องทั้งหมดโดยไม่ต้องค้นหา</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Dear Ms. Lin, thank you for your email. Please see my answers below. The price is valid until June. I will get back to you about the lead time by Wednesday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Dear Ms. Lin, <mark>thank you for your email</mark>. <mark>Please see my answers below.</mark> The price is valid until June. <mark>I will get back to you</mark> about the lead time <mark>by</mark> Wednesday.</div><div class=\"ts-th\">เรียนคุณหลิน ขอบคุณสำหรับอีเมล กรุณาดูคำตอบด้านล่าง ราคาใช้ได้ถึงเดือนมิถุนายน ส่วนระยะเวลาส่งของจะแจ้งกลับภายในวันพุธ</div></div></div></div>","easy":{"say":"ขอ: บอกสิ่งที่ต้องการ + เหตุผล + กำหนดเวลา · ตอบ: ครบทุกข้อ · ติดตาม: อ้างอีเมลเดิมอย่างสุภาพ","eg":["<b>I am following up on</b> my email of 3 May.","ขอติดตามอีเมลวันที่ 3 พฤษภาคม"],"rule":"ทุกคำขอต้องมี \"เมื่อไร\""}},{"id":"problem","en":"Problems, complaints and apologies","th":"แจ้งปัญหา ร้องเรียน ขอโทษ และเสนอทางแก้","intro":"อีเมลแจ้งปัญหาที่ดีบอกข้อเท็จจริง ผลกระทบ และสิ่งที่ต้องการ ส่วนอีเมลขอโทษที่ดียอมรับปัญหา อธิบายสั้นๆ และบอกการแก้ไข","r":[],"tips":[],"items":[{"id":"wk-problem-0","p":0,"s":"ประโยคแจ้งปัญหาใดดีที่สุด?","gap":0,"o":{"A":"40 of the 500 pcs received on 2 May had scratches.","B":"Your parts are bad!","C":"Many parts are not good.","D":"We are angry."},"oth":{},"a":"A","x":"มีจำนวน วันที่ และลักษณะปัญหาชัดเจน","v":[]},{"id":"wk-problem-1","p":0,"s":"We apologize _____ the delay.","gap":1,"o":{"A":"of","B":"about to","C":"for","D":"to"},"oth":{},"a":"C","x":"apologize for + noun / V-ing","v":[]},{"id":"wk-problem-2","p":0,"s":"Please accept our _____ for the error.","gap":1,"o":{"A":"apologize","B":"apologetic","C":"apologies","D":"apology to"},"oth":{},"a":"C","x":"accept our apologies","v":[]},{"id":"wk-problem-3","p":0,"s":"ส่วนใดควรมีในอีเมลขอโทษ?","gap":0,"o":{"A":"คำขอโทษยาวหลายย่อหน้า","B":"โทษผู้อื่น","C":"ไม่ต้องบอกการแก้ไข","D":"ยอมรับปัญหา สาเหตุสั้นๆ และการแก้ไข"},"oth":{},"a":"D","x":"ลูกค้าต้องการรู้ว่าจะไม่เกิดซ้ำ","v":[]},{"id":"wk-problem-4","p":0,"s":"The problem was _____ by a wrong setting.","gap":1,"o":{"A":"cause","B":"caused","C":"causing","D":"causes"},"oth":{},"a":"B","x":"was caused by = เกิดจาก (passive)","v":[]},{"id":"wk-problem-5","p":0,"s":"ประโยคใดเป็นภาษาที่เป็นกลาง?","gap":0,"o":{"A":"The label was missing on two boxes.","B":"You always make mistakes.","C":"Your stupid staff forgot labels.","D":"Nobody cares."},"oth":{},"a":"A","x":"บอกข้อเท็จจริงโดยไม่โจมตีคน","v":[]},{"id":"wk-problem-6","p":0,"s":"To _____ this from happening again, we will add a check.","gap":1,"o":{"A":"prevention","B":"prevent","C":"prevented","D":"preventive"},"oth":{},"a":"B","x":"To + V1: prevent ... from happening","v":[]},{"id":"wk-problem-7","p":0,"s":"\"We are sorry for the inconvenience.\" แปลว่าอะไร?","gap":0,"o":{"A":"ขอโทษที่มาช้า","B":"ขอบคุณที่สะดวก","C":"เราไม่สะดวก","D":"ขออภัยในความไม่สะดวก"},"oth":{},"a":"D","x":"inconvenience = ความไม่สะดวก","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">อีเมลแจ้งปัญหาเหมือน <b>รายงานแพทย์</b>: บอกอาการ (ข้อเท็จจริง) ผลกระทบ และสิ่งที่ต้องการให้รักษา ไม่ใช่บ่นว่าป่วย ส่วนอีเมลขอโทษเหมือน <b>หมอที่ดี</b>: ยอมรับ อธิบาย และบอกแผนการรักษา</div><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">Subject: Quality issue: scratches on part A (PO 7781)</div><div class=\"wd-r\"><span class=\"wd-l\">ข้อเท็จจริง</span><div class=\"wd-t\" lang=\"en\">We received 500 pcs on 2 May. During incoming inspection, 40 pcs (8%) had scratches on the top cover.</div></div><div class=\"wd-r\"><span class=\"wd-l\">ผลกระทบ</span><div class=\"wd-t\" lang=\"en\">We had to stop line 3 for two hours.</div></div><div class=\"wd-r\"><span class=\"wd-l\">สิ่งที่ต้องการ</span><div class=\"wd-t\" lang=\"en\">Please send 40 replacement pcs by 8 May and an 8D report within 10 days.</div></div><div class=\"wd-r\"><span class=\"wd-l\">หลักฐาน</span><div class=\"wd-t\" lang=\"en\">Photos are attached.</div></div></div><figcaption>อีเมลแจ้งปัญหา: ข้อเท็จจริง → ผลกระทบ → สิ่งที่ต้องการ</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>Apologize: We apologize for ...</li><li>Explain briefly: This was caused by ...</li><li>Fix now: We have already ...</li><li>Prevent: To prevent this, we will ...</li><li>Close: Thank you for your patience.</li></ol><figcaption>ห้าขั้นของอีเมลขอโทษ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ขอโทษ</div><div class=\"tf-value\">We apologize for + noun / V-ing</div></div><div class=\"tense-formula\"><div class=\"tf-label\">สาเหตุ</div><div class=\"tf-value\">This was caused by ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ป้องกัน</div><div class=\"tf-value\">To prevent this, we will ...</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>แจ้งปัญหา / ร้องเรียน</b> — ข้อเท็จจริง (อะไร ที่ไหน เมื่อไร เท่าไร) → ผลกระทบ → สิ่งที่ต้องการ<br><span class=\"bv-rx\">We received 500 pcs of part A on 2 May, and 40 pcs had scratches. <small>เราได้รับชิ้นส่วน A 500 ชิ้น วันที่ 2 พฤษภาคม และ 40 ชิ้นมีรอยขีดข่วน</small></span></p><p><b>ขอโทษ</b> — We apologize for ... · Please accept our apologies for ... · We are sorry for the inconvenience.</p><p><b>อธิบายและแก้ไข</b> — This was caused by ... · We have already ... · To prevent this, we will ...<br><span class=\"bv-rx\">We have replaced the damaged parts and added a final check. <small>เราเปลี่ยนชิ้นส่วนที่เสียหายแล้ว และเพิ่มการตรวจขั้นสุดท้าย</small></span></p><p><b>ภาษาที่เป็นกลาง</b> — อธิบายข้อเท็จจริง ไม่กล่าวโทษคน: \"The label was missing\" ดีกว่า \"Your staff forgot the label\"</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We apologize for sending the wrong items.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We apologize for sending the wrong items.</div><div class=\"ex-th thai\">ขออภัยที่ส่งสินค้าผิด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"This was caused by a labeling error.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">This was caused by a labeling error.</div><div class=\"ex-th thai\">สาเหตุคือการติดฉลากผิด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We have already sent the correct parts.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We have already sent the correct parts.</div><div class=\"ex-th thai\">เราส่งชิ้นส่วนที่ถูกต้องไปแล้ว</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Thank you for your patience.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Thank you for your patience.</div><div class=\"ex-th thai\">ขอบคุณที่อดทนรอ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Sorry for inconvenient.</p><p class=\"ok\">✓ Sorry for the inconvenience.</p><small>ใช้ noun inconvenience</small></div><div class=\"bv-m\"><p class=\"no\">✗ We apologize to the delay.</p><p class=\"ok\">✓ We apologize for the delay.</p><small>apologize for + สิ่งที่ผิด / apologize to + คน</small></div><div class=\"bv-m\"><p class=\"no\">✗ Many parts are NG.</p><p class=\"ok\">✓ 40 of 500 pcs (8%) are rejected for scratches.</p><small>NG ไม่ชัด ให้บอกจำนวนและอาการ</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ใส่ตัวเลขเสมอ: จำนวน (40 pcs) สัดส่วน (8%) วันที่ (2 May) หมายเลขอ้างอิง (PO 7781, lot 25) ตัวเลขทำให้ปัญหาชัดและแก้ได้เร็ว</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Dear customer, we apologize for the wrong labels on lot 12. This was caused by a printer setting. We have already replaced all labels, and to prevent this, we added a final check.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Dear customer, <mark>we apologize for</mark> the wrong labels on lot 12. <mark>This was caused by</mark> a printer setting. <mark>We have already</mark> replaced all labels, and <mark>to prevent this</mark>, we added a final check.</div><div class=\"ts-th\">เรียนลูกค้า ขออภัยที่ฉลากล็อต 12 ผิด สาเหตุคือการตั้งค่าเครื่องพิมพ์ เราเปลี่ยนฉลากทั้งหมดแล้ว และเพื่อป้องกัน เราเพิ่มการตรวจขั้นสุดท้าย</div></div></div></div>","easy":{"say":"แจ้งปัญหา: ข้อเท็จจริง (มีตัวเลข) → ผลกระทบ → สิ่งที่ต้องการ · ขอโทษ: ยอมรับ → สาเหตุสั้นๆ → แก้แล้ว → ป้องกัน","eg":["<b>We apologize for</b> the delay. <b>This was caused by</b> ...","ขออภัยที่ล่าช้า สาเหตุคือ..."],"rule":"apologize for + สิ่งที่ผิด · ใส่ตัวเลขเสมอ"}},{"id":"meeting","en":"Meetings: agenda, minutes and action items","th":"การประชุม: วาระ บันทึก และงานที่ต้องทำ","intro":"การประชุมที่ได้ผลมีวาระ (agenda) ก่อน บันทึกการประชุม (minutes) หลัง และรายการงาน (action items) ที่บอกว่าใครทำอะไรเมื่อไร","r":[],"tips":[],"items":[{"id":"wk-meeting-0","p":0,"s":"วลีใดใช้เริ่มประชุม?","gap":0,"o":{"A":"Any other business?","B":"Let's finish.","C":"Let's get started.","D":"Goodbye everyone."},"oth":{},"a":"C","x":"ใช้เปิดการประชุม","v":[]},{"id":"wk-meeting-1","p":0,"s":"\"action item\" ที่ดีต้องมีอะไร?","gap":0,"o":{"A":"ชื่อผู้เข้าประชุม","B":"หัวข้อประชุมอย่างเดียว","C":"งาน ผู้รับผิดชอบ และกำหนดเสร็จ","D":"ห้องประชุม"},"oth":{},"a":"C","x":"Action – Owner – Due date","v":[]},{"id":"wk-meeting-2","p":0,"s":"เอกสารบันทึกสิ่งที่ตกลงในการประชุมเรียกว่าอะไร?","gap":0,"o":{"A":"quotation","B":"agenda","C":"invoice","D":"minutes"},"oth":{},"a":"D","x":"minutes = บันทึกการประชุม","v":[]},{"id":"wk-meeting-3","p":0,"s":"ประโยคใดไม่เห็นด้วยอย่างสุภาพ?","gap":0,"o":{"A":"That is stupid.","B":"I see your point, but the cost is too high.","C":"No way.","D":"You are wrong."},"oth":{},"a":"B","x":"ยอมรับความเห็นก่อน แล้วบอกเหตุผล","v":[]},{"id":"wk-meeting-4","p":0,"s":"Could you _____ what you mean by 'phase 2'?","gap":1,"o":{"A":"clear","B":"clarify","C":"clearly","D":"clarity"},"oth":{},"a":"B","x":"clarify = อธิบายให้ชัด","v":[]},{"id":"wk-meeting-5","p":0,"s":"วลีใดใช้เปลี่ยนไปหัวข้อถัดไป?","gap":0,"o":{"A":"To sum up","B":"Let's move on to the next item.","C":"I agree.","D":"Let's get started."},"oth":{},"a":"B","x":"move on = ไปต่อ","v":[]},{"id":"wk-meeting-6","p":0,"s":"\"To sum up\" ใช้ตอนไหน?","gap":0,"o":{"A":"ขัดจังหวะ","B":"เริ่มประชุม","C":"ถามคำถาม","D":"สรุปก่อนจบ"},"oth":{},"a":"D","x":"sum up = สรุป","v":[]},{"id":"wk-meeting-7","p":0,"s":"เอกสารที่ส่งก่อนประชุมเพื่อบอกหัวข้อเรียกว่าอะไร?","gap":0,"o":{"A":"minutes","B":"report","C":"agenda","D":"receipt"},"oth":{},"a":"C","x":"agenda = วาระการประชุม","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">การประชุมเหมือน <b>การเดินทาง</b>: agenda คือแผนที่ (จะไปที่ไหนบ้าง) ระหว่างทางมีวลีบอกทาง (move on, clarify) และ minutes กับ action items คือรูปถ่ายและรายการของที่ต้องทำหลังกลับบ้าน</div><figure class=\"bv bv-steps\"><ol><li>Agenda: ส่งก่อนประชุม 1 วัน</li><li>Open: Let&#x27;s get started. The purpose is ...</li><li>Discuss: The next item is ... / Could you clarify ...?</li><li>Decide: So we agree to ...</li><li>Close: To sum up, ... / Action items are ...</li><li>Minutes: ส่งภายใน 24 ชั่วโมง</li></ol><figcaption>วงจรการประชุม</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>Action</th><th>Owner</th><th>Due</th></tr></thead><tbody><tr><td>Update the control plan</td><td>Somchai</td><td>20 May</td></tr><tr><td>Send 8D report to customer</td><td>Pop</td><td>22 May</td></tr><tr><td>Order new fixture</td><td>Nok</td><td>31 May</td></tr></tbody></table></div><figcaption>ตาราง action items ในบันทึกการประชุม</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เปิด</div><div class=\"tf-value\">Let&#x27;s get started.</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เปลี่ยนหัวข้อ</div><div class=\"tf-value\">Let&#x27;s move on to ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ปิด</div><div class=\"tf-value\">To sum up, ...</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ก่อนประชุม: agenda</b> — หัวข้อ เวลา ผู้นำเสนอ และสิ่งที่ต้องตัดสินใจ<br><span class=\"bv-rx\">Item 2: Supplier review (Pop, 15 min) – decision needed</span></p><p><b>ระหว่างประชุม: วลีที่ใช้</b> — Let's get started. · The next item is ... · Could you clarify ...? · I'd like to add ... · Let's move on. · To sum up, ...</p><p><b>หลังประชุม: minutes + action items</b> — บันทึกสิ่งที่ตกลงกัน และรายการงาน: Action – Owner – Due date<br><span class=\"bv-rx\">Update the control plan – Somchai – 20 May <small>ปรับแผนควบคุม – สมชาย – 20 พ.ค.</small></span></p><p><b>ขอความเห็น / ไม่เห็นด้วยอย่างสุภาพ</b> — What do you think? · I see your point, but ... · I'm not sure I agree.</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Let&#x27;s move on to item 3.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Let&#x27;s move on to item 3.</div><div class=\"ex-th thai\">ไปที่วาระที่ 3</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Could you clarify the timeline?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Could you clarify the timeline?</div><div class=\"ex-th thai\">ช่วยอธิบายกำหนดเวลาให้ชัดได้ไหม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I&#x27;d like to add one point.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I&#x27;d like to add one point.</div><div class=\"ex-th thai\">ขอเพิ่มอีกหนึ่งประเด็น</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"To sum up, we will change the supplier.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">To sum up, we will change the supplier.</div><div class=\"ex-th thai\">สรุปคือเราจะเปลี่ยนผู้จัดหา</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Minute of meeting</p><p class=\"ok\">✓ Minutes of the meeting</p><small>ใช้รูปพหูพจน์ minutes</small></div><div class=\"bv-m\"><p class=\"no\">✗ Let&#x27;s discuss about the cost.</p><p class=\"ok\">✓ Let&#x27;s discuss the cost.</p><small>discuss ไม่ต้องมี about</small></div><div class=\"bv-m\"><p class=\"no\">✗ Action: improve quality (ไม่มีชื่อ ไม่มีวันที่)</p><p class=\"ok\">✓ Action: add a 100% visual check – Nok – 15 May</p><small>งานที่ไม่มีเจ้าของและวันที่มักไม่ถูกทำ</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ส่ง minutes ภายใน 24 ชั่วโมงหลังประชุม และเริ่มด้วยรายการ action items ด้านบน คนส่วนใหญ่อ่านแค่ส่วนนั้น</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Let&#x27;s get started. The first item is the supplier review. ... Let&#x27;s move on. ... To sum up, Nok will order a new fixture by 31 May.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Let&#x27;s get started.</mark> The first <mark>item</mark> is the supplier review. ... <mark>Let&#x27;s move on.</mark> ... <mark>To sum up</mark>, Nok will order a new fixture by 31 May.</div><div class=\"ts-th\">เริ่มกันเลย วาระแรกคือการทบทวนผู้จัดหา ... ไปต่อกัน ... สรุปคือนกจะสั่งฟิกซ์เจอร์ใหม่ภายใน 31 พฤษภาคม</div></div></div></div>","easy":{"say":"ประชุมที่ได้ผล: agenda ก่อน → วลีนำการประชุม → minutes + action items (ใคร ทำอะไร เมื่อไร) หลังประชุม","eg":["Action: update the plan – <b>Somchai</b> – <b>20 May</b>","งาน – ผู้รับผิดชอบ – กำหนดเสร็จ"],"rule":"ทุก action ต้องมี owner และ due date"}},{"id":"report","en":"Writing reports","th":"การเขียนรายงาน","intro":"รายงานงานที่ดีให้ข้อสรุปก่อนรายละเอียด (bottom line up front) และแยกข้อเท็จจริงออกจากความเห็นชัดเจน","r":[],"tips":[],"items":[{"id":"wk-report-0","p":0,"s":"ส่วนใดของรายงานควรอยู่ต้นสุดและสั้นที่สุด?","gap":0,"o":{"A":"Background","B":"Summary","C":"Method","D":"Appendix"},"oth":{},"a":"B","x":"ผู้บริหารมักอ่านเฉพาะ summary","v":[]},{"id":"wk-report-1","p":0,"s":"The results _____ that the new process is faster.","gap":1,"o":{"A":"shows of","B":"showing","C":"to show","D":"show"},"oth":{},"a":"D","x":"The results (พหูพจน์) show that ...","v":[]},{"id":"wk-report-2","p":0,"s":"ประโยคใดเป็น passive voice ที่ใช้ในรายงาน?","gap":0,"o":{"A":"Testing is fun.","B":"We test fifty samples now.","C":"Test fifty samples!","D":"Fifty samples were tested."},"oth":{},"a":"D","x":"were + V3","v":[]},{"id":"wk-report-3","p":0,"s":"We recommend _____ the old filter.","gap":1,"o":{"A":"replace","B":"replaced","C":"to replacing","D":"replacing"},"oth":{},"a":"D","x":"recommend + V-ing","v":[]},{"id":"wk-report-4","p":0,"s":"ประโยคใดเป็น \"ความเห็น\" ไม่ใช่ข้อเท็จจริง?","gap":0,"o":{"A":"We believe the main cause is humidity.","B":"The test started on 3 May.","C":"50 samples were tested.","D":"The yield was 92%."},"oth":{},"a":"A","x":"We believe = ความเห็น","v":[]},{"id":"wk-report-5","p":0,"s":"The defect rate _____ from 5% to 2%.","gap":1,"o":{"A":"decreased","B":"decreasing","C":"was decrease","D":"decrease"},"oth":{},"a":"A","x":"อดีต: decreased from ... to ...","v":[]},{"id":"wk-report-6","p":0,"s":"ส่วนใดอธิบายวิธีการทดสอบ?","gap":0,"o":{"A":"Conclusion","B":"Method","C":"Recommendations","D":"Summary"},"oth":{},"a":"B","x":"Method = วิธีการ","v":[]},{"id":"wk-report-7","p":0,"s":"The temperature _____ stable at 25 °C.","gap":1,"o":{"A":"remained","B":"remains of","C":"remain to","D":"was remaining of"},"oth":{},"a":"A","x":"remain stable = คงที่","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">รายงานงานเหมือน <b>ข่าวหน้าหนึ่ง</b>: พาดหัวและย่อหน้าแรกบอกเรื่องสำคัญที่สุดก่อน (summary) รายละเอียดตามมาทีหลัง ผู้บริหารที่มีเวลา 1 นาทีต้องได้คำตอบจากย่อหน้าแรก</div><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">Report: Reducing solder defects on Line 2</div><div class=\"wd-r\"><span class=\"wd-l\">Summary</span><div class=\"wd-t\" lang=\"en\">Solder defects fell from 5.1% to 1.8% after the reflow profile was changed. We recommend applying the new profile to Line 3.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Background</span><div class=\"wd-t\" lang=\"en\">Line 2 had a high defect rate in Q1.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Method</span><div class=\"wd-t\" lang=\"en\">300 boards were tested with the new profile from 1 to 14 May.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Findings</span><div class=\"wd-t\" lang=\"en\">Defects decreased by 65%. Cycle time remained stable.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Recommendations</span><div class=\"wd-t\" lang=\"en\">We recommend updating the work instruction and training operators on Line 3.</div></div></div><figcaption>รายงานที่บอกข้อสรุปก่อน</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ข้อเท็จจริง</th><th>ความเห็น</th><th>คำแนะนำ</th></tr></thead><tbody><tr><td>The yield was 92%.</td><td>We believe the cause is humidity.</td><td>We recommend adding a dryer.</td></tr><tr><td>300 boards were tested.</td><td>This suggests the profile is better.</td><td>We suggest training all operators.</td></tr></tbody></table></div><figcaption>แยกสามชนิดของประโยคให้ชัด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ผล</div><div class=\"tf-value\">The data shows / indicates that ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ตัวเลข</div><div class=\"tf-value\">increased / decreased by X% / remained stable</div></div><div class=\"tense-formula\"><div class=\"tf-label\">แนะนำ</div><div class=\"tf-value\">We recommend + V-ing</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>โครงสร้างรายงาน</b> — Summary → Background → Method → Findings / Results → Conclusion → Recommendations</p><p><b>คำกริยาในรายงาน</b> — show, indicate, suggest (ผลบอก), increase / decrease / remain stable (ตัวเลข), recommend (แนะนำ)<br><span class=\"bv-rx\">The data <b>indicates</b> that the defect rate <b>decreased</b> by 30%. <small>ข้อมูลชี้ว่าอัตราของเสียลดลง 30%</small></span></p><p><b>passive voice ในรายงาน</b> — เน้นสิ่งที่ทำ ไม่เน้นคนทำ: 50 samples were tested. The machine was adjusted.</p><p><b>ข้อเท็จจริง vs ความเห็น</b> — ข้อเท็จจริง: The yield was 92%. / ความเห็น: We believe the main cause is ... / แนะนำ: We recommend replacing ...</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The results indicate that the new design is more reliable.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The results indicate that the new design is more reliable.</div><div class=\"ex-th thai\">ผลบ่งชี้ว่าแบบใหม่เชื่อถือได้มากกว่า</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Output increased by 12% in May.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Output increased by 12% in May.</div><div class=\"ex-th thai\">ผลผลิตเพิ่มขึ้น 12% ในเดือนพฤษภาคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The samples were measured at 25 °C.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The samples were measured at 25 °C.</div><div class=\"ex-th thai\">ตัวอย่างวัดที่ 25 องศาเซลเซียส</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We recommend extending the trial for two weeks.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We recommend extending the trial for two weeks.</div><div class=\"ex-th thai\">เราแนะนำให้ขยายการทดลองอีกสองสัปดาห์</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ We recommend to replace the filter.</p><p class=\"ok\">✓ We recommend replacing the filter. / We recommend that the filter be replaced.</p><small>recommend + V-ing หรือ that-clause</small></div><div class=\"bv-m\"><p class=\"no\">✗ The defect rate decreased 5% to 2%.</p><p class=\"ok\">✓ The defect rate decreased from 5% to 2%.</p><small>ใช้ from ... to ...</small></div><div class=\"bv-m\"><p class=\"no\">✗ The result is very good (ไม่มีตัวเลข)</p><p class=\"ok\">✓ The yield improved from 88% to 95%.</p><small>รายงานต้องมีตัวเลข</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> แยก &quot;by&quot; กับ &quot;to&quot;: increased &lt;b&gt;by&lt;/b&gt; 10% = เพิ่มขึ้นอีก 10% / increased &lt;b&gt;to&lt;/b&gt; 10% = เพิ่มขึ้นจนเป็น 10%</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Summary: After the change, scrap decreased by 40%. The data indicates that the new tool is more stable. We recommend using it on all lines.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Summary:</mark> After the change, scrap <mark>decreased by</mark> 40%. <mark>The data indicates</mark> that the new tool is more stable. <mark>We recommend</mark> using it on all lines.</div><div class=\"ts-th\">สรุป: หลังการเปลี่ยน ของเสียลดลง 40% ข้อมูลชี้ว่าเครื่องมือใหม่เสถียรกว่า เราแนะนำให้ใช้กับทุกไลน์</div></div></div></div>","easy":{"say":"รายงานเหมือนข่าวหน้าหนึ่ง: ข้อสรุปก่อน รายละเอียดทีหลัง ใช้ตัวเลขเสมอ และแยกข้อเท็จจริงกับความเห็น","eg":["Defects <b>decreased by</b> 65%. <b>We recommend</b> using the new profile.","ของเสียลดลง 65% เราแนะนำให้ใช้โปรไฟล์ใหม่"],"rule":"Summary ก่อน · มีตัวเลข · recommend + V-ing"}},{"id":"present","en":"Presentations and describing charts","th":"การนำเสนอและการบรรยายกราฟ","intro":"การนำเสนอที่ดีบอกโครงสร้างก่อน ใช้วลีนำทาง (signposting) และบรรยายกราฟด้วยคำที่ถูกต้อง","r":[],"tips":[],"items":[{"id":"wk-present-0","p":0,"s":"วลีใดใช้บอกว่ากำลังจะไปส่วนถัดไป?","gap":0,"o":{"A":"Let's move on to the next slide.","B":"Thank you for listening.","C":"Any questions?","D":"Good morning."},"oth":{},"a":"A","x":"move on = ไปต่อ","v":[]},{"id":"wk-present-1","p":0,"s":"เส้นกราฟขึ้นๆ ลงๆ ตลอด ใช้คำกริยาใด?","gap":0,"o":{"A":"peak","B":"remain stable","C":"increase steadily","D":"fluctuate"},"oth":{},"a":"D","x":"fluctuate = ผันผวน ขึ้นลง","v":[]},{"id":"wk-present-2","p":0,"s":"ยอดขายถึงจุดสูงสุดในเดือนมิถุนายน คือข้อใด?","gap":0,"o":{"A":"Sales dropped in June.","B":"Sales remained in June.","C":"Sales fluctuated in June.","D":"Sales peaked in June."},"oth":{},"a":"D","x":"peak = ถึงจุดสูงสุด","v":[]},{"id":"wk-present-3","p":0,"s":"Costs rose _____ from 100 to 101.","gap":1,"o":{"A":"dramatically","B":"slightly","C":"significantly","D":"sharply"},"oth":{},"a":"B","x":"เพิ่มนิดเดียว = slightly","v":[]},{"id":"wk-present-4","p":0,"s":"As you can _____ on this slide, the trend is positive.","gap":1,"o":{"A":"look","B":"watch","C":"view at","D":"see"},"oth":{},"a":"D","x":"As you can see ... (วลีสำเร็จรูป)","v":[]},{"id":"wk-present-5","p":0,"s":"เส้นกราฟแนวนอนไม่เปลี่ยน ใช้วลีใด?","gap":0,"o":{"A":"peaked","B":"fell dramatically","C":"remained stable","D":"rose sharply"},"oth":{},"a":"C","x":"remain stable = คงที่","v":[]},{"id":"wk-present-6","p":0,"s":"I've _____ my talk into three parts.","gap":1,"o":{"A":"divide","B":"dividing","C":"divided","D":"division"},"oth":{},"a":"C","x":"I've divided ... = ฉันแบ่ง ... (present perfect)","v":[]},{"id":"wk-present-7","p":0,"s":"คำใดตรงข้ามกับ \"rise\"?","gap":0,"o":{"A":"fall","B":"peak","C":"remain","D":"fluctuate"},"oth":{},"a":"A","x":"rise ขึ้น / fall ลง","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">การนำเสนอเหมือน <b>ไกด์นำเที่ยว</b>: บอกเส้นทางก่อน (I have three parts) ระหว่างทางบอกว่าอยู่ตรงไหน (Let's move on to ...) และตอนจบสรุปสิ่งที่เห็น (To sum up) ผู้ฟังจะไม่หลงทาง</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>รูปกราฟ</th><th>คำกริยา</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>↗ ขึ้น</td><td>rise / increase / go up</td><td>Sales rose by 10%.</td></tr><tr><td>↘ ลง</td><td>fall / decrease / drop</td><td>Costs fell slightly.</td></tr><tr><td>→ คงที่</td><td>remain stable / level off</td><td>Demand remained stable.</td></tr><tr><td>〰 ขึ้นลง</td><td>fluctuate</td><td>Prices fluctuated.</td></tr><tr><td>⛰ สูงสุด</td><td>peak / reach a peak</td><td>Output peaked in June.</td></tr><tr><td>⌣ ต่ำสุด</td><td>reach a low / bottom out</td><td>Sales reached a low in May.</td></tr></tbody></table></div><figcaption>คำบรรยายแนวโน้มของกราฟ</figcaption></figure><figure class=\"bv bv-scale\"><div class=\"bv-sr\"><span class=\"bv-sw\">sharply / dramatically</span><span class=\"bv-sb\"><i style=\"width:100%\"></i></span><span class=\"bv-st\">มาก ฉับพลัน</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">significantly</span><span class=\"bv-sb\"><i style=\"width:75%\"></i></span><span class=\"bv-st\">มากพอสมควร</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">steadily</span><span class=\"bv-sb\"><i style=\"width:55%\"></i></span><span class=\"bv-st\">สม่ำเสมอ</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">gradually</span><span class=\"bv-sb\"><i style=\"width:40%\"></i></span><span class=\"bv-st\">ค่อยๆ</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">slightly</span><span class=\"bv-sb\"><i style=\"width:15%\"></i></span><span class=\"bv-st\">เล็กน้อย</span></div><figcaption>adverb บอกขนาดการเปลี่ยนแปลง</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เปิด</div><div class=\"tf-value\">Today I&#x27;d like to talk about ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">นำทาง</div><div class=\"tf-value\">Let&#x27;s move on to ... / As you can see, ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">กราฟ</div><div class=\"tf-value\">verb + adverb (rose sharply, fell slightly)</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>เปิดและบอกโครงสร้าง</b> — Today I'd like to talk about ... · I've divided my talk into three parts. · First, ... Then, ... Finally, ...</p><p><b>นำทาง (signposting)</b> — Let's move on to ... · As you can see on this slide, ... · This brings me to ... · To sum up, ...</p><p><b>บรรยายแนวโน้ม</b> — rise / increase / go up · fall / decrease / drop · remain stable · fluctuate (ขึ้นลง) · peak (สูงสุด) · reach a low (ต่ำสุด)<br><span class=\"bv-rx\">Sales <b>rose sharply</b> in March and <b>peaked</b> in June. <small>ยอดขายพุ่งขึ้นในเดือนมีนาคมและสูงสุดในเดือนมิถุนายน</small></span></p><p><b>ขนาดของการเปลี่ยนแปลง</b> — slightly (เล็กน้อย) · gradually (ค่อยๆ) · steadily (สม่ำเสมอ) · significantly / sharply (มาก / ฉับพลัน)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Today I&#x27;d like to talk about our Q2 results.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Today I&#x27;d like to talk about our Q2 results.</div><div class=\"ex-th thai\">วันนี้ขอพูดเรื่องผลไตรมาสสอง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"As you can see, defects fell sharply after May.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">As you can see, defects fell sharply after May.</div><div class=\"ex-th thai\">อย่างที่เห็น ของเสียลดลงมากหลังเดือนพฤษภาคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Output increased steadily throughout the year.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Output increased steadily throughout the year.</div><div class=\"ex-th thai\">ผลผลิตเพิ่มขึ้นสม่ำเสมอตลอดปี</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"To sum up, the project is on track.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">To sum up, the project is on track.</div><div class=\"ex-th thai\">สรุปคือโครงการเป็นไปตามแผน</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ The sales are increase.</p><p class=\"ok\">✓ Sales increased. / Sales are increasing.</p><small>increase เป็นกริยา ไม่ใช้กับ are แบบนี้</small></div><div class=\"bv-m\"><p class=\"no\">✗ rose up</p><p class=\"ok\">✓ rose</p><small>rise มีความหมายว่าขึ้นอยู่แล้ว</small></div><div class=\"bv-m\"><p class=\"no\">✗ a sharp increase of 2% (เปลี่ยนนิดเดียว)</p><p class=\"ok\">✓ a slight increase of 2%</p><small>เลือก adverb ให้ตรงขนาดจริง</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> จำรูปกริยาไม่ปกติ: rise – rose – risen, fall – fell – fallen, grow – grew – grown ใช้บ่อยมากในการบรรยายกราฟ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Today I&#x27;d like to talk about our quality results. As you can see, defects fell sharply in March and remained stable after that. To sum up, the new process works.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Today I&#x27;d like to talk about</mark> our quality results. <mark>As you can see</mark>, defects <mark>fell sharply</mark> in March and <mark>remained stable</mark> after that. <mark>To sum up</mark>, the new process works.</div><div class=\"ts-th\">วันนี้ขอพูดเรื่องผลด้านคุณภาพ อย่างที่เห็น ของเสียลดลงมากในเดือนมีนาคม และคงที่หลังจากนั้น สรุปคือกระบวนการใหม่ได้ผล</div></div></div></div>","easy":{"say":"นำเสนอแบบไกด์: บอกเส้นทาง → บอกว่าอยู่ตรงไหน → สรุป บรรยายกราฟด้วย กริยา + adverb","eg":["Sales <b>rose sharply</b> and <b>peaked</b> in June.","ยอดขายพุ่งขึ้นและสูงสุดในเดือนมิถุนายน"],"rule":"rise/fall/remain/fluctuate/peak + slightly/gradually/sharply"}},{"id":"chat","en":"Phone calls, chat and abbreviations","th":"โทรศัพท์ แชท และคำย่อในงาน","intro":"การคุยโทรศัพท์และแชทในงานต้องสั้น ชัด และสุภาพ และควรรู้คำย่อที่ใช้บ่อยในอีเมลและแชท","r":[],"tips":[],"items":[{"id":"wk-chat-0","p":0,"s":"\"FYI\" หมายถึงอะไร?","gap":0,"o":{"A":"ขอบคุณ","B":"เพื่อทราบ (for your information)","C":"ยังไม่กำหนด","D":"รีบด่วน"},"oth":{},"a":"B","x":"FYI = for your information","v":[]},{"id":"wk-chat-1","p":0,"s":"\"ETA 3 p.m.\" หมายถึงอะไร?","gap":0,"o":{"A":"ประชุมบ่าย 3","B":"ออกเดินทางบ่าย 3","C":"คาดว่าจะถึงบ่าย 3 โมง","D":"หมดเวลาบ่าย 3"},"oth":{},"a":"C","x":"ETA = estimated time of arrival","v":[]},{"id":"wk-chat-2","p":0,"s":"\"Please send it by EOD.\" หมายถึงอะไร?","gap":0,"o":{"A":"ส่งตอนเช้า","B":"ส่งสัปดาห์หน้า","C":"ส่งภายในสิ้นวันทำงาน","D":"ไม่ต้องส่ง"},"oth":{},"a":"C","x":"EOD = end of day","v":[]},{"id":"wk-chat-3","p":0,"s":"วิธีแนะนำตัวทางโทรศัพท์ที่ถูกต้องคือข้อใด?","gap":0,"o":{"A":"Here is Pop.","B":"I am Pop from ABC speaking now you.","C":"Me Pop.","D":"This is Pop from ABC Electronics."},"oth":{},"a":"D","x":"This is + ชื่อ + from + บริษัท","v":[]},{"id":"wk-chat-4","p":0,"s":"ถ้าฟังไม่ทัน ควรพูดว่าอะไร?","gap":0,"o":{"A":"Could you repeat that, please?","B":"I hear nothing.","C":"What?","D":"Again!"},"oth":{},"a":"A","x":"สุภาพและชัด","v":[]},{"id":"wk-chat-5","p":0,"s":"ข้อความแชทใดดีที่สุด?","gap":0,"o":{"A":"Hi","B":"Hi Ken, could you send the test report for lot 25 by 3 p.m.?","C":"Are you there?","D":"???"},"oth":{},"a":"B","x":"บอกเรื่องและสิ่งที่ต้องการในข้อความเดียว","v":[]},{"id":"wk-chat-6","p":0,"s":"\"i.e.\" ต่างจาก \"e.g.\" อย่างไร?","gap":0,"o":{"A":"i.e. = เช่น / e.g. = คือ","B":"เหมือนกัน","C":"ทั้งสองแปลว่า และอื่นๆ","D":"i.e. = คือ (อธิบาย) / e.g. = เช่น (ยกตัวอย่าง)"},"oth":{},"a":"D","x":"i.e. = id est (that is) / e.g. = exempli gratia (for example)","v":[]},{"id":"wk-chat-7","p":0,"s":"The date is TBD. หมายถึงอะไร?","gap":0,"o":{"A":"วันพรุ่งนี้","B":"วันที่ผ่านมา","C":"ยังไม่กำหนดวัน","D":"ยกเลิกแล้ว"},"oth":{},"a":"C","x":"TBD = to be determined / decided","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">แชทงานที่ส่งแค่ \"Hi\" แล้วรอ เหมือน <b>เคาะประตูแล้ววิ่งหนี</b> ผู้รับต้องรอว่าจะถามอะไร ให้บอกเรื่องทั้งหมดในข้อความแรก ส่วนโทรศัพท์ที่ไม่มีหน้าตาให้ดู ต้องทวนข้อมูลสำคัญเสมอ (Let me confirm ...)</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>คำย่อ</th><th>เต็ม</th><th>ความหมาย</th></tr></thead><tbody><tr><td>ASAP</td><td>as soon as possible</td><td>เร็วที่สุด</td></tr><tr><td>FYI</td><td>for your information</td><td>เพื่อทราบ</td></tr><tr><td>ETA</td><td>estimated time of arrival</td><td>เวลาที่คาดว่าจะถึง</td></tr><tr><td>EOD</td><td>end of day</td><td>สิ้นวันทำงาน</td></tr><tr><td>TBD</td><td>to be determined</td><td>ยังไม่กำหนด</td></tr><tr><td>N/A</td><td>not applicable</td><td>ไม่เกี่ยวข้อง / ไม่มี</td></tr><tr><td>e.g.</td><td>for example</td><td>เช่น</td></tr><tr><td>i.e.</td><td>that is</td><td>คือ</td></tr><tr><td>PO / PR</td><td>purchase order / request</td><td>ใบสั่งซื้อ / ใบขอซื้อ</td></tr></tbody></table></div><figcaption>คำย่อในอีเมลและแชทงาน</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>This is Pop from ABC Electronics.</li><li>I&#x27;m calling about the order for PO 4512.</li><li>Could you tell me the new delivery date?</li><li>Let me confirm: 8 May, 300 pcs. Is that right?</li><li>Thank you. Have a nice day.</li></ol><figcaption>โครงสร้างการโทรติดต่องาน</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">แนะนำตัว</div><div class=\"tf-value\">This is + ชื่อ + from + บริษัท</div></div><div class=\"tense-formula\"><div class=\"tf-label\">จุดประสงค์</div><div class=\"tf-value\">I&#x27;m calling about ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ทวน</div><div class=\"tf-value\">Let me confirm: ...</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>โทรศัพท์</b> — This is Pop from ABC. · Could I speak to ...? · I'm calling about ... · Could you repeat that, please? · Let me confirm: ...</p><p><b>ฝากข้อความ / ตรวจความเข้าใจ</b> — Could I leave a message? · Could you spell that, please? · So, just to confirm, the meeting is at 3 p.m.?</p><p><b>แชทงาน (Teams, LINE, Slack)</b> — ประโยคแรกบอกเรื่องเลย ไม่ส่งแค่ \"Hi\" แล้วรอ · ใส่บริบทและสิ่งที่ต้องการในข้อความเดียว<br><span class=\"bv-rx\">Hi Anna, could you check PO 4512? The delivery date shows 10 May, but we agreed 8 May.</span></p><p><b>คำย่อที่ใช้บ่อย</b> — ASAP (เร็วที่สุด) · FYI (เพื่อทราบ) · ETA (เวลาที่คาดว่าจะถึง) · EOD (สิ้นวันทำงาน) · TBD (ยังไม่กำหนด) · PO (ใบสั่งซื้อ) · Q&A · e.g. (เช่น) · i.e. (คือ)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"I&#x27;m calling about the invoice for May.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">I&#x27;m calling about the invoice for May.</div><div class=\"ex-th thai\">โทรมาเรื่องใบแจ้งหนี้เดือนพฤษภาคม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Could you spell your name, please?\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Could you spell your name, please?</div><div class=\"ex-th thai\">ช่วยสะกดชื่อให้หน่อยได้ไหม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"FYI, the meeting moved to Room 5.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">FYI, the meeting moved to Room 5.</div><div class=\"ex-th thai\">เพื่อทราบ การประชุมย้ายไปห้อง 5</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The ETA of the truck is 2 p.m.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The ETA of the truck is 2 p.m.</div><div class=\"ex-th thai\">รถบรรทุกคาดว่าจะถึงบ่ายสองโมง</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ I am Pop speaking.</p><p class=\"ok\">✓ This is Pop (speaking).</p><small>โทรศัพท์ใช้ This is ...</small></div><div class=\"bv-m\"><p class=\"no\">✗ Hi (แล้วรอ 10 นาที)</p><p class=\"ok\">✓ Hi Ken, could you send ...?</p><small>บอกเรื่องในข้อความแรก</small></div><div class=\"bv-m\"><p class=\"no\">✗ ใช้ ASAP กับทุกเรื่อง</p><p class=\"ok\">✓ ใส่เวลาจริง: by 3 p.m.</p><small>ASAP บ่อยเกินไปทำให้คนไม่รู้ว่าเรื่องไหนด่วนจริง</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> เวลาฟังตัวเลขทางโทรศัพท์ ระวัง -teen กับ -ty (fifteen / fifty) ให้ทวนว่า &quot;one-five or five-zero?&quot;</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"This is Pop from ABC. I&#x27;m calling about PO 4512. ... Let me confirm: 300 pcs, ETA Friday 2 p.m. FYI, our dock closes at 5.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>This is</mark> Pop <mark>from</mark> ABC. <mark>I&#x27;m calling about</mark> PO 4512. ... <mark>Let me confirm</mark>: 300 pcs, ETA Friday 2 p.m. <mark>FYI</mark>, our dock closes at 5.</div><div class=\"ts-th\">ป๊อปจาก ABC พูดค่ะ/ครับ โทรมาเรื่องใบสั่งซื้อ 4512 ... ขอทวนนะ 300 ชิ้น คาดว่าถึงวันศุกร์บ่ายสอง เพื่อทราบ ท่าขนของปิดห้าโมงเย็น</div></div></div></div>","easy":{"say":"โทร: This is + ชื่อ + from + บริษัท แล้วทวนข้อมูลเสมอ · แชท: บอกเรื่องทั้งหมดในข้อความแรก · รู้คำย่อ FYI, ETA, EOD, TBD","eg":["<b>This is</b> Pop <b>from</b> ABC. <b>Let me confirm</b>: ...",""],"rule":"ไม่ส่งแค่ \"Hi\" · ทวนตัวเลขทุกครั้ง"}},{"id":"plain","en":"Clear and concise writing","th":"เขียนให้กระชับและชัดเจน (plain English)","intro":"งานเขียนที่ดีที่สุดคืองานที่อ่านครั้งเดียวเข้าใจ ใช้ประโยคสั้น คำง่าย ประธานชัด และตัดคำที่ไม่จำเป็น","r":[],"tips":[],"items":[{"id":"wk-plain-0","p":0,"s":"วลีใดกระชับที่สุดแทน \"due to the fact that\"?","gap":0,"o":{"A":"owing to the fact that","B":"for the reason that","C":"because","D":"in view of the fact that"},"oth":{},"a":"C","x":"because สั้นและชัดที่สุด","v":[]},{"id":"wk-plain-1","p":0,"s":"\"in order to reduce costs\" เขียนให้สั้นลงได้ว่าอะไร?","gap":0,"o":{"A":"in order for reduce costs","B":"to reduce costs","C":"reducing to costs","D":"for reducing of costs"},"oth":{},"a":"B","x":"in order to → to","v":[]},{"id":"wk-plain-2","p":0,"s":"ประโยคใดชัดที่สุด?","gap":0,"o":{"A":"It is planned that delivery will occur.","B":"The supplier will deliver the parts on Monday.","C":"The parts will be delivered on Monday by the supplier as per the agreed plan.","D":"Delivery of parts is to be done on Monday by supplier."},"oth":{},"a":"B","x":"active voice ประธานชัด ไม่ฟุ่มเฟือย","v":[]},{"id":"wk-plain-3","p":0,"s":"\"at this point in time\" แทนด้วยคำใด?","gap":0,"o":{"A":"in this moment of time","B":"presently at the moment","C":"at this time point","D":"now"},"oth":{},"a":"D","x":"now","v":[]},{"id":"wk-plain-4","p":0,"s":"\"a large number of\" แทนด้วยคำใด?","gap":0,"o":{"A":"a lot number","B":"big number","C":"large of","D":"many"},"oth":{},"a":"D","x":"many","v":[]},{"id":"wk-plain-5","p":0,"s":"ประโยคควรยาวประมาณเท่าไร?","gap":0,"o":{"A":"50 คำขึ้นไป","B":"5 คำเท่านั้น","C":"ไม่จำกัด","D":"15–20 คำ"},"oth":{},"a":"D","x":"ประโยคสั้นอ่านเข้าใจง่ายกว่า","v":[]},{"id":"wk-plain-6","p":0,"s":"รายการขั้นตอน 5 ข้อ ควรเขียนอย่างไร?","gap":0,"o":{"A":"แยกเป็นข้อมีหมายเลข","B":"ใส่ไว้ในหัวเรื่อง","C":"เขียนต่อกันในย่อหน้าเดียว","D":"ไม่ต้องเขียน"},"oth":{},"a":"A","x":"ตัวเลขช่วยให้ทำตามลำดับได้ถูก","v":[]},{"id":"wk-plain-7","p":0,"s":"\"We would like to inform you that the price will increase.\" เขียนให้ตรงขึ้นได้ว่าอะไร?","gap":0,"o":{"A":"We inform that increase.","B":"The price will increase on 1 July.","C":"Please be informed of increasing.","D":"Price increase information is to be informed."},"oth":{},"a":"B","x":"บอกเรื่องตรงๆ และเพิ่มข้อมูลสำคัญ (วันที่)","v":[]}],"grp":"Business Writing — งานเขียนธุรกิจ","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">การเขียนกระชับเหมือน <b>การตัดแต่งต้นไม้</b>: ตัดกิ่งที่ไม่ออกผล (คำฟุ่มเฟือย) ต้นไม้จะแข็งแรงขึ้น ผู้อ่านในงานมีเวลาน้อย ทุกคำที่ไม่จำเป็นคือเวลาที่เสียไป</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ยาว (ฟุ่มเฟือย)</th><th>สั้น (ชัด)</th></tr></thead><tbody><tr><td>in order to</td><td>to</td></tr><tr><td>due to the fact that</td><td>because</td></tr><tr><td>at this point in time</td><td>now</td></tr><tr><td>a large number of</td><td>many</td></tr><tr><td>in the event that</td><td>if</td></tr><tr><td>make a decision</td><td>decide</td></tr><tr><td>carry out an inspection</td><td>inspect</td></tr><tr><td>prior to</td><td>before</td></tr></tbody></table></div><figcaption>ตัดคำฟุ่มเฟือย</figcaption></figure><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">ก่อน → หลัง</div><div class=\"wd-r\"><span class=\"wd-l\">ก่อน (42 คำ)</span><div class=\"wd-t\" lang=\"en\">We would like to inform you that due to the fact that the machine is under maintenance at this point in time, the delivery of the parts will be carried out by us on Friday instead of Wednesday as previously planned.</div></div><div class=\"wd-r\"><span class=\"wd-l\">หลัง (17 คำ)</span><div class=\"wd-t\" lang=\"en\">The machine is under maintenance now, so we will deliver the parts on Friday, not Wednesday.</div></div></div><figcaption>ความหมายเท่าเดิม สั้นลงครึ่งหนึ่ง</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ประโยค</div><div class=\"tf-value\">15–20 คำ หนึ่งความคิด</div></div><div class=\"tense-formula\"><div class=\"tf-label\">คำ</div><div class=\"tf-value\">คำสั้นแทนวลียาว</div></div><div class=\"tense-formula\"><div class=\"tf-label\">รูปแบบ</div><div class=\"tf-value\">bullet / ตัวเลข / ตัวหนา</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ประโยคสั้น หนึ่งความคิดต่อประโยค</b> — ประโยคละ 15–20 คำ ถ้ายาวกว่านั้นให้แยก</p><p><b>ตัดคำฟุ่มเฟือย</b> — in order to → to · due to the fact that → because · at this point in time → now · a large number of → many</p><p><b>active voice เมื่อคนทำสำคัญ</b> — The supplier will send the parts. ชัดกว่า The parts will be sent by the supplier. (ใช้ passive เมื่อคนทำไม่สำคัญ)</p><p><b>ใช้ bullet และตัวเลข</b> — รายการ ขั้นตอน และตัวเลขให้แยกบรรทัด ผู้อ่านจะสแกนได้เร็ว</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please reply by Friday.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please reply by Friday.</div><div class=\"ex-th thai\">กรุณาตอบภายในวันศุกร์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"We will inspect all units before shipping.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">We will inspect all units before shipping.</div><div class=\"ex-th thai\">เราจะตรวจทุกเครื่องก่อนส่ง</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The line stopped because the sensor failed.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The line stopped because the sensor failed.</div><div class=\"ex-th thai\">ไลน์หยุดเพราะเซนเซอร์เสีย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Before you start, check the air pressure.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Before you start, check the air pressure.</div><div class=\"ex-th thai\">ก่อนเริ่ม ให้ตรวจแรงดันลม</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ We will make an investigation of the issue.</p><p class=\"ok\">✓ We will investigate the issue.</p><small>ใช้กริยาตรงแทน make + noun</small></div><div class=\"bv-m\"><p class=\"no\">✗ In the event that the machine stops, ...</p><p class=\"ok\">✓ If the machine stops, ...</p><small>if สั้นกว่า</small></div><div class=\"bv-m\"><p class=\"no\">✗ ประโยคเดียว 60 คำ มี and 5 ครั้ง</p><p class=\"ok\">✓ แยกเป็น 3–4 ประโยค</p><small>ประโยคยาวทำให้ผู้อ่านหลงประเด็น</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ทดสอบง่ายๆ: อ่านออกเสียงประโยค ถ้าต้องหยุดหายใจกลางประโยค แปลว่ายาวเกินไป ให้แยก</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Old: &quot;Due to the fact that the truck was late, an inspection was carried out at a later point in time.&quot; New: &quot;The truck was late, so we inspected the goods later.&quot;\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Old: &quot;<mark>Due to the fact that</mark> the truck was late, <mark>an inspection was carried out</mark> <mark>at a later point in time</mark>.&quot; New: &quot;The truck was late, so we <mark>inspected</mark> the goods <mark>later</mark>.&quot;</div><div class=\"ts-th\">แบบเดิมยาวและอ้อม แบบใหม่สั้นและชัด ความหมายเท่าเดิม</div></div></div></div>","easy":{"say":"เขียนกระชับ = ประโยคสั้น คำง่าย ประธานชัด ตัดวลียาวที่มีคำสั้นแทนได้","eg":["<b>due to the fact that</b> → because · <b>in order to</b> → to",""],"rule":"อ่านครั้งเดียวต้องเข้าใจ"}},{"id":"spec","en":"Specifications: shall, should, may","th":"ภาษาใน specification: shall, should, may","intro":"specification (spec) คือเอกสารบอกข้อกำหนด คำช่วยแต่ละคำมีน้ำหนักต่างกัน และค่าตัวเลขต้องมีหน่วยกับค่าเผื่อ (tolerance) เสมอ","r":[],"tips":[],"items":[{"id":"wk-spec-0","p":0,"s":"ใน spec คำใดหมายถึง \"ต้องทำ\" (บังคับ)?","gap":0,"o":{"A":"may","B":"shall","C":"can","D":"should"},"oth":{},"a":"B","x":"shall = ข้อกำหนดที่ต้องปฏิบัติ","v":[]},{"id":"wk-spec-1","p":0,"s":"ใน spec คำใดหมายถึง \"แนะนำ แต่ไม่บังคับ\"?","gap":0,"o":{"A":"should","B":"must","C":"shall","D":"will"},"oth":{},"a":"A","x":"should = ข้อแนะนำ","v":[]},{"id":"wk-spec-2","p":0,"s":"ค่า 10.0 ± 0.1 mm ยอมรับได้ในช่วงใด?","gap":0,"o":{"A":"9.9–10.1 mm","B":"9.99–10.01 mm","C":"9.0–11.0 mm","D":"10.0–10.1 mm"},"oth":{},"a":"A","x":"ค่าตั้ง ± ค่าเผื่อ","v":[]},{"id":"wk-spec-3","p":0,"s":"ชิ้นงานวัดได้ 10.3 mm (spec 10.0 ± 0.1 mm) เป็นอย่างไร?","gap":0,"o":{"A":"nominal","B":"compliant","C":"out of tolerance","D":"within tolerance"},"oth":{},"a":"C","x":"เกินขอบเขต 10.1 mm","v":[]},{"id":"wk-spec-4","p":0,"s":"\"rated voltage 24 V\" หมายถึงอะไร?","gap":0,"o":{"A":"ราคาของแรงดัน","B":"แรงดันต่ำสุดที่อันตราย","C":"แรงดันพิกัด (ที่ออกแบบให้ใช้) 24 V","D":"แรงดันที่วัดได้วันนี้"},"oth":{},"a":"C","x":"rated = ค่าพิกัด","v":[]},{"id":"wk-spec-5","p":0,"s":"ข้อกำหนดใด \"วัดได้\" ที่สุด?","gap":0,"o":{"A":"The tape shall be strong.","B":"The tape is nice.","C":"Peel strength shall be at least 5 N.","D":"The tape should be good."},"oth":{},"a":"C","x":"มีตัวเลขและหน่วยตรวจสอบได้","v":[]},{"id":"wk-spec-6","p":0,"s":"The cable _____ be replaced by the user. (อนุญาต ไม่บังคับ)","gap":1,"o":{"A":"shall","B":"may","C":"must","D":"should not"},"oth":{},"a":"B","x":"may = อนุญาต","v":[]},{"id":"wk-spec-7","p":0,"s":"\"compliant with ISO 9001\" หมายถึงอะไร?","gap":0,"o":{"A":"ร้องเรียน ISO 9001","B":"ไม่เกี่ยวกับ ISO 9001","C":"แข่งกับ ISO 9001","D":"เป็นไปตามมาตรฐาน ISO 9001"},"oth":{},"a":"D","x":"compliant with = เป็นไปตาม","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">spec เหมือน <b>สัญญากับเครื่องจักร</b>: ทุกคำมีน้ำหนักทางกฎหมาย shall คือ \"ต้อง\" ถ้าไม่ทำถือว่าผิดสัญญา should คือ \"ควร\" may คือ \"ทำได้ถ้าต้องการ\" เขียนผิดคำเดียว ความหมายของข้อกำหนดเปลี่ยนทันที</div><figure class=\"bv bv-scale\"><div class=\"bv-sr\"><span class=\"bv-sw\">shall / must</span><span class=\"bv-sb\"><i style=\"width:100%\"></i></span><span class=\"bv-st\">ต้อง (บังคับ)</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">should</span><span class=\"bv-sb\"><i style=\"width:65%\"></i></span><span class=\"bv-st\">ควร (แนะนำ)</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">may</span><span class=\"bv-sb\"><i style=\"width:35%\"></i></span><span class=\"bv-st\">อาจ / อนุญาต</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">can</span><span class=\"bv-sb\"><i style=\"width:20%\"></i></span><span class=\"bv-st\">สามารถ (เป็นไปได้)</span></div><figcaption>น้ำหนักของคำในเอกสารข้อกำหนด (ISO/IEC Directives)</figcaption></figure><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">Specification: Cable assembly CA-210 (Rev. C)</div><div class=\"wd-r\"><span class=\"wd-l\">Material</span><div class=\"wd-t\" lang=\"en\">Conductor shall be tinned copper, 0.5 mm².</div></div><div class=\"wd-r\"><span class=\"wd-l\">Dimension</span><div class=\"wd-t\" lang=\"en\">Length: 300 ± 5 mm</div></div><div class=\"wd-r\"><span class=\"wd-l\">Electrical</span><div class=\"wd-t\" lang=\"en\">Rated voltage: 30 V DC. Insulation resistance shall be ≥ 100 MΩ at 500 V DC.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Environment</span><div class=\"wd-t\" lang=\"en\">Operating temperature: −20 °C to +85 °C</div></div><div class=\"wd-r\"><span class=\"wd-l\">Compliance</span><div class=\"wd-t\" lang=\"en\">The assembly shall be compliant with RoHS and REACH.</div></div></div><figcaption>ตัวอย่าง spec ที่วัดได้ทุกข้อ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ข้อบังคับ</div><div class=\"tf-value\">X shall be ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ค่าและค่าเผื่อ</div><div class=\"tf-value\">nominal ± tolerance + unit</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ช่วง</div><div class=\"tf-value\">min – max / ≥ ≤</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>คำบอกระดับข้อกำหนด</b> — shall = ต้อง (ข้อบังคับ) · should = ควร (แนะนำ) · may = อาจ / อนุญาต (เลือกได้) · can = สามารถ (เป็นไปได้)<br><span class=\"bv-rx\">The housing <b>shall</b> be made of ABS. <small>ตัวเรือนต้องทำจาก ABS</small></span></p><p><b>ค่ากับค่าเผื่อ</b> — nominal (ค่าตั้ง) ± tolerance · min / max · within / out of tolerance<br><span class=\"bv-rx\">Length: 25.0 ± 0.2 mm <small>ความยาว 25.0 บวกลบ 0.2 มม. (24.8–25.2 มม.)</small></span></p><p><b>คำที่ใช้บ่อย</b> — requirement, dimension, material, finish, rated (พิกัด), operating temperature, compliant with (เป็นไปตาม)<br><span class=\"bv-rx\">The product is <b>compliant with</b> RoHS. <small>ผลิตภัณฑ์เป็นไปตาม RoHS</small></span></p><p><b>spec ที่ดีวัดได้</b> — หลีกเลี่ยงคำกว้างๆ เช่น \"strong\", \"good quality\" ให้ใช้ตัวเลขและวิธีทดสอบ<br><span class=\"bv-rx\">Peel strength shall be ≥ 5 N (test method TM-07). <small>แรงลอกต้องไม่น้อยกว่า 5 นิวตัน (วิธีทดสอบ TM-07)</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The surface shall be free of scratches.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The surface shall be free of scratches.</div><div class=\"ex-th thai\">พื้นผิวต้องไม่มีรอยขีดข่วน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Torque: 1.2 ± 0.1 N·m\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Torque: 1.2 ± 0.1 N·m</div><div class=\"ex-th thai\">แรงบิด 1.2 ± 0.1 นิวตันเมตร</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Gloves should be worn during assembly.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Gloves should be worn during assembly.</div><div class=\"ex-th thai\">ควรสวมถุงมือขณะประกอบ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The product is rated for 10,000 cycles.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The product is rated for 10,000 cycles.</div><div class=\"ex-th thai\">ผลิตภัณฑ์มีพิกัด 10,000 รอบ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ The part should be RoHS compliant. (หมายถึงบังคับ)</p><p class=\"ok\">✓ The part shall be RoHS compliant.</p><small>ถ้าบังคับต้องใช้ shall</small></div><div class=\"bv-m\"><p class=\"no\">✗ Length 25 mm (ไม่มีค่าเผื่อ)</p><p class=\"ok\">✓ Length 25.0 ± 0.2 mm</p><small>ไม่มี tolerance จะตรวจรับไม่ได้</small></div><div class=\"bv-m\"><p class=\"no\">✗ The glue shall be strong.</p><p class=\"ok\">✓ Shear strength shall be ≥ 20 N.</p><small>ข้อกำหนดต้องวัดได้</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> อ่าน spec ลูกค้าให้ขีดเส้นใต้ทุกคำว่า shall แล้วทำเป็นรายการตรวจ (checklist) ทุก shall ต้องมีวิธีพิสูจน์ว่าทำได้</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The new specification says the board shall pass a 500 V test, the coating should be clear, and the label may be printed or engraved. All values have a tolerance.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The new <mark>specification</mark> says the board <mark>shall</mark> pass a 500 V test, the coating <mark>should</mark> be clear, and the label <mark>may</mark> be printed or engraved. All values have a <mark>tolerance</mark>.</div><div class=\"ts-th\">spec ใหม่ระบุว่าแผงวงจรต้องผ่านการทดสอบ 500 V สารเคลือบควรใส และฉลากอาจพิมพ์หรือแกะสลักก็ได้ ทุกค่ามีค่าเผื่อ</div></div></div></div>","easy":{"say":"spec คือสัญญา: shall = ต้อง · should = ควร · may = ทำได้ถ้าต้องการ และทุกตัวเลขต้องมีหน่วยกับค่าเผื่อ","eg":["Length: 25.0 <b>±</b> 0.2 mm · The part <b>shall</b> be ...",""],"rule":"shall ต้อง · should ควร · may อาจ · ทุกค่ามี ± และหน่วย"}},{"id":"units","en":"Numbers, units and measurement","th":"ตัวเลข หน่วย และการวัด","intro":"ในงานเทคนิค การอ่านและเขียนตัวเลขกับหน่วยผิดอาจทำให้ผลิตผิดทั้งล็อต รู้วิธีอ่านออกเสียง วิธีเขียน และคำที่ใช้กับการวัด","r":[],"tips":[],"items":[{"id":"wk-units-0","p":0,"s":"\"0.25 mm\" อ่านออกเสียงอย่างไร?","gap":0,"o":{"A":"zero comma two five","B":"twenty-five millimetres","C":"zero point two five millimetres","D":"zero point twenty-five millimetre"},"oth":{},"a":"C","x":"ตัวเลขหลังจุดอ่านทีละตัว","v":[]},{"id":"wk-units-1","p":0,"s":"ข้อใดเขียนถูกตาม SI?","gap":0,"o":{"A":"5kgs.","B":"5 kg","C":"5 Kg","D":"5 kgs"},"oth":{},"a":"B","x":"เว้นวรรค ตัวพิมพ์เล็ก ไม่เติม s","v":[]},{"id":"wk-units-2","p":0,"s":"1,000 ppm เท่ากับกี่เปอร์เซ็นต์?","gap":0,"o":{"A":"0.01%","B":"0.1%","C":"10%","D":"1%"},"oth":{},"a":"B","x":"1 ppm = 0.0001% ดังนั้น 1,000 ppm = 0.1%","v":[]},{"id":"wk-units-3","p":0,"s":"\"10 MΩ\" กับ \"10 mΩ\" ต่างกันอย่างไร?","gap":0,"o":{"A":"ไม่มีความต่าง","B":"M = มิลลิ / m = เมกะ","C":"เหมือนกัน","D":"M = เมกะ (ล้าน) / m = มิลลิ (หนึ่งในพัน)"},"oth":{},"a":"D","x":"ตัวพิมพ์ใหญ่-เล็กเปลี่ยนค่าเป็นพันล้านเท่า","v":[]},{"id":"wk-units-4","p":0,"s":"การปรับเครื่องมือวัดให้ตรงกับมาตรฐานเรียกว่าอะไร?","gap":0,"o":{"A":"installation","B":"inspection","C":"calibration","D":"production"},"oth":{},"a":"C","x":"calibrate = สอบเทียบ","v":[]},{"id":"wk-units-5","p":0,"s":"\"The reading is 4.98 V.\" คำว่า reading หมายถึงอะไร?","gap":0,"o":{"A":"ค่าที่อ่านได้จากเครื่องวัด","B":"ความเร็ว","C":"แรงดันพิกัด","D":"การอ่านหนังสือ"},"oth":{},"a":"A","x":"reading ในงานวัด = ค่าที่อ่านได้","v":[]},{"id":"wk-units-6","p":0,"s":"\"twenty-five degrees Celsius\" เขียนอย่างไร?","gap":0,"o":{"A":"25 °C","B":"25 deg","C":"25 oC","D":"25 C°"},"oth":{},"a":"A","x":"SI: ตัวเลข เว้นวรรค °C","v":[]},{"id":"wk-units-7","p":0,"s":"ความสามารถในการวัดซ้ำแล้วได้ค่าเดิมเรียกว่าอะไร?","gap":0,"o":{"A":"resolution","B":"repeatability","C":"accuracy","D":"tolerance"},"oth":{},"a":"B","x":"repeatability = ความสามารถวัดซ้ำได้ค่าเดิม (accuracy = ใกล้ค่าจริง)","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ตัวเลขในงานเทคนิคเหมือน <b>รหัสผ่าน</b>: ผิดตัวเดียวเข้าไม่ได้ m กับ M ต่างกันพันล้านเท่า 0.5 กับ 5 ต่างกันสิบเท่า ภาษาอังกฤษจึงมีกฎการอ่านและเขียนที่ชัดเจน</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>เขียน</th><th>อ่านออกเสียง</th></tr></thead><tbody><tr><td>0.5 mm</td><td>zero point five millimetres</td></tr><tr><td>3.3 V</td><td>three point three volts</td></tr><tr><td>10 kΩ</td><td>ten kilohms</td></tr><tr><td>4.7 µF</td><td>four point seven microfarads</td></tr><tr><td>25 °C</td><td>twenty-five degrees Celsius</td></tr><tr><td>1/4&quot;</td><td>a quarter of an inch</td></tr><tr><td>±0.1</td><td>plus or minus zero point one</td></tr><tr><td>50 ppm</td><td>fifty parts per million</td></tr></tbody></table></div><figcaption>การอ่านตัวเลขและหน่วย</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>accuracy</th><th>precision / repeatability</th></tr></thead><tbody><tr><td>ค่าที่วัดใกล้ค่าจริง</td><td>วัดซ้ำได้ค่าใกล้กันเอง</td></tr><tr><td>ปรับด้วยการสอบเทียบ (calibration)</td><td>ดูจากการวัดซ้ำหลายครั้ง</td></tr><tr><td>ยิงธนูโดนกลางเป้า</td><td>ยิงธนูกลุ่มเดียวกัน (อาจไม่โดนกลาง)</td></tr></tbody></table></div><figcaption>สองคำที่คนมักใช้ปนกัน</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เขียน</div><div class=\"tf-value\">ตัวเลข + เว้นวรรค + หน่วย</div></div><div class=\"tense-formula\"><div class=\"tf-label\">อ่านทศนิยม</div><div class=\"tf-value\">point + ตัวเลขทีละตัว</div></div><div class=\"tense-formula\"><div class=\"tf-label\">สัดส่วน</div><div class=\"tf-value\">% = /100 · ppm = /1,000,000</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>อ่านออกเสียง</b> — 0.5 mm = zero point five millimetres · 3.3 V = three point three volts · 10 kΩ = ten kilohms · 25 °C = twenty-five degrees Celsius</p><p><b>เขียนให้ถูกตาม SI</b> — เว้นวรรคระหว่างตัวเลขกับหน่วย (5 mm, 220 V, 25 °C) · สัญลักษณ์หน่วยไม่เติม s (5 kg ไม่ใช่ 5 kgs) · ตัวพิมพ์มีความหมาย (m = milli, M = mega)</p><p><b>ปริมาณสัดส่วน</b> — % = ต่อร้อย · ppm = ต่อล้าน (1 ppm = 0.0001%) · ใช้ ppm วัดของเสียในอุตสาหกรรม<br><span class=\"bv-rx\">The defect rate is 50 ppm. <small>อัตราของเสีย 50 ชิ้นในล้านชิ้น</small></span></p><p><b>คำเกี่ยวกับการวัด</b> — measure, reading (ค่าที่อ่านได้), accuracy (ความแม่น), precision / repeatability (ความเที่ยง), calibrate (สอบเทียบ), resolution (ความละเอียด)<br><span class=\"bv-rx\">Calibrate the gauge every six months. <small>สอบเทียบเกจทุกหกเดือน</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The gap is zero point two millimetres.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The gap is zero point two millimetres.</div><div class=\"ex-th thai\">ช่องว่าง 0.2 มิลลิเมตร</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The oven temperature is 245 °C.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The oven temperature is 245 °C.</div><div class=\"ex-th thai\">อุณหภูมิเตา 245 องศาเซลเซียส</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Our target is below 100 ppm.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Our target is below 100 ppm.</div><div class=\"ex-th thai\">เป้าหมายของเราต่ำกว่า 100 ppm</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The caliper has a resolution of 0.01 mm.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The caliper has a resolution of 0.01 mm.</div><div class=\"ex-th thai\">เวอร์เนียร์มีความละเอียด 0.01 มม.</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ 5 kgs</p><p class=\"ok\">✓ 5 kg</p><small>สัญลักษณ์หน่วยไม่เติม s</small></div><div class=\"bv-m\"><p class=\"no\">✗ 25°c</p><p class=\"ok\">✓ 25 °C</p><small>C ตัวใหญ่ และเว้นวรรคตาม SI</small></div><div class=\"bv-m\"><p class=\"no\">✗ accuracy = repeatability</p><p class=\"ok\">✓ สองคำต่างกัน</p><small>แม่น (ใกล้ค่าจริง) กับ เที่ยง (ซ้ำได้)</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ประเทศที่ใช้ภาษาอังกฤษใช้จุด (.) เป็นทศนิยมและจุลภาค (,) คั่นหลักพัน: 1,250.5 แต่ยุโรปหลายประเทศกลับกัน (1.250,5) ระวังเวลาอ่าน spec จากยุโรป</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The technician calibrated the meter. The reading was 4.98 volts, within the spec of 5.00 ± 0.05 V. The defect rate this month is 35 ppm.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The technician <mark>calibrated</mark> the meter. The <mark>reading</mark> was <mark>4.98 volts</mark>, within the spec of <mark>5.00 ± 0.05 V</mark>. The defect rate this month is <mark>35 ppm</mark>.</div><div class=\"ts-th\">ช่างสอบเทียบมิเตอร์ ค่าที่อ่านได้ 4.98 โวลต์ อยู่ใน spec 5.00 ± 0.05 V อัตราของเสียเดือนนี้ 35 ppm</div></div></div></div>","easy":{"say":"ตัวเลขคือรหัสผ่าน ผิดตัวเดียวผิดทั้งล็อต: อ่านทศนิยมทีละตัว เว้นวรรคก่อนหน่วย ไม่เติม s และระวังตัวพิมพ์ m / M","eg":["0.5 mm = zero <b>point</b> five millimetres",""],"rule":"ตัวเลข␣หน่วย · ไม่เติม s · m ≠ M · 1 ppm = 0.0001%"}},{"id":"sop","en":"Work instructions and SOPs","th":"เขียนคู่มือการทำงาน (SOP / Work Instruction)","intro":"คู่มือการทำงานต้องให้คนทำตามได้ถูกต้องทุกครั้ง ใช้ประโยคคำสั่ง ขั้นตอนมีหมายเลข หนึ่งการกระทำต่อหนึ่งขั้น และคำเตือนชัดเจน","r":[],"tips":[],"items":[{"id":"wk-sop-0","p":0,"s":"ขั้นตอนใดเขียนแบบ work instruction ได้ดีที่สุด?","gap":0,"o":{"A":"Screws tight.","B":"You may want to tighten some screws.","C":"The screws are tightened by the operator if possible.","D":"Tighten the four screws to 0.6 N·m."},"oth":{},"a":"D","x":"ประโยคคำสั่ง มีจำนวน และค่าแรงบิด","v":[]},{"id":"wk-sop-1","p":0,"s":"คำเตือนระดับใดรุนแรงที่สุด?","gap":0,"o":{"A":"WARNING","B":"NOTE","C":"CAUTION","D":"DANGER"},"oth":{},"a":"D","x":"DANGER = จะเกิดอันตรายร้ายแรงหรือเสียชีวิต","v":[]},{"id":"wk-sop-2","p":0,"s":"_____ removing the cover, turn off the power.","gap":1,"o":{"A":"Then","B":"Until","C":"Before","D":"Finally"},"oth":{},"a":"C","x":"Before + V-ing = ก่อน...","v":[]},{"id":"wk-sop-3","p":0,"s":"Hold the button _____ the light turns green.","gap":1,"o":{"A":"after","B":"before","C":"unless","D":"until"},"oth":{},"a":"D","x":"until = จนกระทั่ง","v":[]},{"id":"wk-sop-4","p":0,"s":"\"Do not touch the heater.\" เป็นประโยคชนิดใด?","gap":0,"o":{"A":"คำแนะนำทั่วไป","B":"คำถาม","C":"คำสั่งห้าม (negative imperative)","D":"passive"},"oth":{},"a":"C","x":"Do not + V1","v":[]},{"id":"wk-sop-5","p":0,"s":"ขั้นตอนที่รวม 3 การกระทำในข้อเดียวมีปัญหาอะไร?","gap":0,"o":{"A":"ไม่มีปัญหา","B":"คนทำอาจข้ามบางการกระทำ","C":"ปลอดภัยกว่า","D":"อ่านเร็วขึ้น"},"oth":{},"a":"B","x":"หนึ่งขั้นควรมีหนึ่งการกระทำ","v":[]},{"id":"wk-sop-6","p":0,"s":"NOTE ในคู่มือใช้สำหรับอะไร?","gap":0,"o":{"A":"อันตรายถึงชีวิต","B":"ข้อมูลเพิ่มเติมที่ช่วยให้ทำงานถูก","C":"ชื่อผู้เขียน","D":"คำสั่งห้าม"},"oth":{},"a":"B","x":"NOTE ไม่ใช่คำเตือนอันตราย","v":[]},{"id":"wk-sop-7","p":0,"s":"_____, record the result on the check sheet.","gap":1,"o":{"A":"Before","B":"Finally","C":"Unless","D":"Until"},"oth":{},"a":"B","x":"Finally = ขั้นสุดท้าย","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">work instruction เหมือน <b>สูตรอาหาร</b>: ถ้าเขียนว่า \"ใส่เกลือนิดหน่อย\" แต่ละคนใส่ไม่เท่ากัน ต้องเขียน \"ใส่เกลือ 1 ช้อนชา\" งานในโรงงานก็เหมือนกัน \"ขันให้แน่น\" ไม่พอ ต้องเป็น \"ขันด้วยแรงบิด 0.6 N·m\"</div><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">WI-ASSY-014: Fitting the cover (Rev. B)</div><div class=\"wd-r\"><span class=\"wd-l\">Tools</span><div class=\"wd-t\" lang=\"en\">Torque screwdriver (0.6 N·m), ESD wrist strap</div></div><div class=\"wd-r\"><span class=\"wd-l\">⚠ CAUTION</span><div class=\"wd-t\" lang=\"en\">Wear the ESD wrist strap. Static can damage the board.</div></div><div class=\"wd-r\"><span class=\"wd-l\">1</span><div class=\"wd-t\" lang=\"en\">Place the board in fixture F-12.</div></div><div class=\"wd-r\"><span class=\"wd-l\">2</span><div class=\"wd-t\" lang=\"en\">Put the cover on the board. Align the two holes with the pins.</div></div><div class=\"wd-r\"><span class=\"wd-l\">3</span><div class=\"wd-t\" lang=\"en\">Insert four M2 screws.</div></div><div class=\"wd-r\"><span class=\"wd-l\">4</span><div class=\"wd-t\" lang=\"en\">Tighten the screws to 0.6 N·m in the order A–B–C–D.</div></div><div class=\"wd-r\"><span class=\"wd-l\">5</span><div class=\"wd-t\" lang=\"en\">Check that the cover does not move.</div></div><div class=\"wd-r\"><span class=\"wd-l\">NOTE</span><div class=\"wd-t\" lang=\"en\">If a screw does not fit, do not force it. Call the line leader.</div></div></div><figcaption>work instruction: เครื่องมือ → คำเตือน → ขั้นตอนมีหมายเลข → หมายเหตุ</figcaption></figure><figure class=\"bv bv-scale\"><div class=\"bv-sr\"><span class=\"bv-sw\">DANGER</span><span class=\"bv-sb\"><i style=\"width:100%\"></i></span><span class=\"bv-st\">จะเกิดอันตรายร้ายแรง / เสียชีวิต</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">WARNING</span><span class=\"bv-sb\"><i style=\"width:75%\"></i></span><span class=\"bv-st\">อาจบาดเจ็บสาหัส</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">CAUTION</span><span class=\"bv-sb\"><i style=\"width:50%\"></i></span><span class=\"bv-st\">อาจบาดเจ็บเล็กน้อย</span></div><div class=\"bv-sr\"><span class=\"bv-sw\">NOTICE / NOTE</span><span class=\"bv-sb\"><i style=\"width:20%\"></i></span><span class=\"bv-st\">อุปกรณ์เสียหาย / ข้อมูลเพิ่มเติม</span></div><figcaption>ระดับคำเตือนตาม ANSI Z535</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ขั้นตอน</div><div class=\"tf-value\">หมายเลข + กริยารูปเดิม + สิ่งของ + ค่า</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ลำดับ</div><div class=\"tf-value\">Before / After + V-ing · until</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ห้าม</div><div class=\"tf-value\">Do not + V1</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ประโยคคำสั่ง (imperative)</b> — ขึ้นต้นด้วยกริยารูปเดิม: Check ... · Insert ... · Tighten ... · Do not ...<br><span class=\"bv-rx\"><b>Tighten</b> the four screws to 0.6 N·m. <small>ขันสกรูสี่ตัวด้วยแรงบิด 0.6 นิวตันเมตร</small></span></p><p><b>หนึ่งขั้น หนึ่งการกระทำ</b> — แยกขั้นตอน ใส่หมายเลข ใส่ค่าที่ต้องใช้และเครื่องมือ</p><p><b>คำบอกลำดับ</b> — First, Then, Next, After that, Finally · before / after + V-ing · until (จนกระทั่ง)<br><span class=\"bv-rx\">Press the button <b>until</b> the LED turns green. <small>กดปุ่มจนไฟ LED เป็นสีเขียว</small></span></p><p><b>คำเตือน (ANSI Z535)</b> — DANGER = จะเกิดอันตรายร้ายแรงหรือเสียชีวิต · WARNING = อาจบาดเจ็บสาหัส · CAUTION = อาจบาดเจ็บเล็กน้อย · NOTICE / NOTE = ความเสียหายต่ออุปกรณ์หรือข้อมูลเพิ่มเติม</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Turn off the power before you open the cover.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Turn off the power before you open the cover.</div><div class=\"ex-th thai\">ปิดไฟก่อนเปิดฝาครอบ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Do not touch the heater; it is hot.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Do not touch the heater; it is hot.</div><div class=\"ex-th thai\">ห้ามแตะฮีตเตอร์ ร้อน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Wait until the temperature is below 40 °C.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Wait until the temperature is below 40 °C.</div><div class=\"ex-th thai\">รอจนอุณหภูมิต่ำกว่า 40 องศาเซลเซียส</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Record the serial number on the check sheet.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Record the serial number on the check sheet.</div><div class=\"ex-th thai\">บันทึกหมายเลขเครื่องลงในใบตรวจ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ The screws should be tightened properly.</p><p class=\"ok\">✓ Tighten the screws to 0.6 N·m.</p><small>ใช้คำสั่งและค่าที่วัดได้แทน &quot;properly&quot;</small></div><div class=\"bv-m\"><p class=\"no\">✗ Open cover and check fuse and replace if broken.</p><p class=\"ok\">✓ 1. Open the cover. 2. Check the fuse. 3. If the fuse is broken, replace it.</p><small>แยกหนึ่งการกระทำต่อหนึ่งขั้น</small></div><div class=\"bv-m\"><p class=\"no\">✗ WARNING: Please read the manual.</p><p class=\"ok\">✓ NOTE: Read the manual before first use.</p><small>WARNING ใช้เฉพาะเมื่อมีความเสี่ยงบาดเจ็บ</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ใส่รูปประกอบทุกขั้นที่ทำได้ และวางคำเตือนไว้ &quot;ก่อน&quot; ขั้นที่อันตราย ไม่ใช่หลัง คนอ่านต้องรู้ก่อนลงมือ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"First, put on the ESD strap. Then place the board in the fixture. Tighten the screws to 0.6 N·m. Do not force a screw. Finally, record the result.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>First</mark>, put on the ESD strap. <mark>Then</mark> place the board in the fixture. <mark>Tighten</mark> the screws to 0.6 N·m. <mark>Do not</mark> force a screw. <mark>Finally</mark>, record the result.</div><div class=\"ts-th\">ขั้นแรก ใส่สายรัดข้อมือ ESD จากนั้นวางแผงวงจรในฟิกซ์เจอร์ ขันสกรูด้วยแรงบิด 0.6 N·m ห้ามฝืนขันสกรู สุดท้ายบันทึกผล</div></div></div></div>","easy":{"say":"คู่มือการทำงานเหมือนสูตรอาหาร: ทุกขั้นขึ้นต้นด้วยกริยา มีหมายเลข หนึ่งการกระทำ และค่าที่วัดได้","eg":["3. <b>Tighten</b> the four screws to <b>0.6 N·m</b>.","ขันสกรูสี่ตัวด้วยแรงบิด 0.6 นิวตันเมตร"],"rule":"กริยาขึ้นต้น · หนึ่งขั้นหนึ่งการกระทำ · ใส่ค่า · คำเตือนไว้ก่อนขั้นอันตราย"}},{"id":"describe","en":"Describing parts and processes","th":"บรรยายชิ้นส่วน หน้าที่ และกระบวนการ","intro":"ภาษาบรรยายชิ้นส่วนใช้รูปประโยคชุดเดียวกันซ้ำๆ: ทำจากอะไร ประกอบด้วยอะไร ใช้ทำอะไร ต่อกับอะไร และกระบวนการใช้ passive voice","r":[],"tips":[],"items":[{"id":"wk-describe-0","p":0,"s":"The cable assembly _____ of three wires and two connectors.","gap":1,"o":{"A":"consist","B":"is consisting","C":"contains of","D":"consists"},"oth":{},"a":"D","x":"consists of = ประกอบด้วย","v":[]},{"id":"wk-describe-1","p":0,"s":"The housing is made _____ aluminum.","gap":1,"o":{"A":"in","B":"of","C":"from by","D":"with of"},"oth":{},"a":"B","x":"be made of + วัสดุ","v":[]},{"id":"wk-describe-2","p":0,"s":"The fan is used to _____ the processor.","gap":1,"o":{"A":"cools","B":"cooling","C":"cool","D":"cooled"},"oth":{},"a":"C","x":"be used to + V1 (หน้าที่)","v":[]},{"id":"wk-describe-3","p":0,"s":"The filter prevents dust _____ entering the unit.","gap":1,"o":{"A":"for","B":"from","C":"to","D":"of"},"oth":{},"a":"B","x":"prevent ... from + V-ing","v":[]},{"id":"wk-describe-4","p":0,"s":"The sensor is _____ to the main board by a cable.","gap":1,"o":{"A":"connecting","B":"connect","C":"connection","D":"connected"},"oth":{},"a":"D","x":"be connected to","v":[]},{"id":"wk-describe-5","p":0,"s":"ประโยคใดบรรยายกระบวนการแบบ passive?","gap":0,"o":{"A":"AOI inspect the boards yesterday.","B":"Inspecting boards is fun.","C":"The boards are inspected by AOI.","D":"Inspect the boards."},"oth":{},"a":"C","x":"are + V3","v":[]},{"id":"wk-describe-6","p":0,"s":"The label is located _____ the back of the unit.","gap":1,"o":{"A":"to","B":"in of","C":"on","D":"at on"},"oth":{},"a":"C","x":"on the back = ด้านหลัง","v":[]},{"id":"wk-describe-7","p":0,"s":"The battery _____ the device to run for 8 hours.","gap":1,"o":{"A":"allows","B":"makes to","C":"lets to","D":"allows that"},"oth":{},"a":"A","x":"allow + object + to V1","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">การบรรยายชิ้นส่วนเหมือน <b>การแนะนำสมาชิกในทีม</b>: บอกว่าเป็นใคร (ทำจากอะไร) มีอะไรบ้าง (ประกอบด้วย) ทำหน้าที่อะไร (is used to) และยืนอยู่ตรงไหน (is mounted on) ใช้โครงประโยคเดิมซ้ำได้กับทุกชิ้นส่วน</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>บอกอะไร</th><th>รูปประโยค</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>วัสดุ</td><td>is made of + วัสดุ</td><td>The case is made of ABS.</td></tr><tr><td>ส่วนประกอบ</td><td>consists of + ส่วนต่างๆ</td><td>It consists of a PCB and a cover.</td></tr><tr><td>หน้าที่</td><td>is used to + V1</td><td>The relay is used to switch the motor.</td></tr><tr><td>ป้องกัน</td><td>prevents X from + V-ing</td><td>The cover prevents water from entering.</td></tr><tr><td>ตำแหน่ง</td><td>is mounted on / attached to</td><td>The LED is mounted on the front panel.</td></tr></tbody></table></div><figcaption>โครงประโยคบรรยายชิ้นส่วน</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>The boards are cleaned.</li><li>Solder paste is printed on the pads.</li><li>Components are placed by the machine.</li><li>The boards are reflowed at 245 °C.</li><li>The boards are inspected by AOI.</li></ol><figcaption>กระบวนการ SMT บรรยายด้วย passive voice</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ส่วนประกอบ</div><div class=\"tf-value\">consists of / is made of</div></div><div class=\"tense-formula\"><div class=\"tf-label\">หน้าที่</div><div class=\"tf-value\">is used to + V1</div></div><div class=\"tense-formula\"><div class=\"tf-label\">กระบวนการ</div><div class=\"tf-value\">is / are + V3</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ส่วนประกอบและวัสดุ</b> — consists of / is made up of (ประกอบด้วย) · is made of (ทำจาก) · contains (บรรจุ)<br><span class=\"bv-rx\">The module <b>consists of</b> a PCB, a housing and a cable. <small>โมดูลประกอบด้วยแผงวงจร ตัวเรือน และสาย</small></span></p><p><b>หน้าที่</b> — is used to + V1 / is used for + V-ing / allows ... to / prevents ... from + V-ing<br><span class=\"bv-rx\">The fuse <b>is used to protect</b> the circuit. <small>ฟิวส์ใช้ป้องกันวงจร</small></span></p><p><b>ตำแหน่งและการต่อ</b> — is attached to / is connected to / is mounted on / is located at / next to / above / below<br><span class=\"bv-rx\">The sensor <b>is mounted on</b> the left side. <small>เซนเซอร์ติดตั้งอยู่ด้านซ้าย</small></span></p><p><b>กระบวนการ (passive)</b> — First, the boards are cleaned. Then, solder paste is printed. Next, components are placed. Finally, the boards are inspected.</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The heat sink is made of aluminum.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The heat sink is made of aluminum.</div><div class=\"ex-th thai\">ฮีตซิงก์ทำจากอะลูมิเนียม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The gasket prevents water from entering.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The gasket prevents water from entering.</div><div class=\"ex-th thai\">ปะเก็นป้องกันไม่ให้น้ำเข้า</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The display is connected to the main board.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The display is connected to the main board.</div><div class=\"ex-th thai\">จอแสดงผลต่อกับแผงวงจรหลัก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Each unit is tested for 30 minutes.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Each unit is tested for 30 minutes.</div><div class=\"ex-th thai\">ทุกเครื่องได้รับการทดสอบ 30 นาที</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ It is consist of three parts.</p><p class=\"ok\">✓ It consists of three parts.</p><small>consist เป็นกริยาแท้ ไม่ใช้กับ is</small></div><div class=\"bv-m\"><p class=\"no\">✗ The fan is used to cooling.</p><p class=\"ok\">✓ The fan is used to cool ... / is used for cooling.</p><small>used to + V1 หรือ used for + V-ing</small></div><div class=\"bv-m\"><p class=\"no\">✗ The cover prevents water to enter.</p><p class=\"ok\">✓ The cover prevents water from entering.</p><small>prevent ... from + V-ing</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ระวัง &quot;is used to + V1&quot; (ใช้เพื่อ) กับ &quot;is used to + V-ing&quot; (เคยชินกับ) เช่น The tool is used to cut wire. / I am used to working nights.</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The power module consists of a transformer, a PCB and a metal case. The case is made of aluminum and is used to remove heat. First, the PCB is tested; then it is mounted in the case.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The power module <mark>consists of</mark> a transformer, a PCB and a metal case. The case <mark>is made of</mark> aluminum and <mark>is used to</mark> remove heat. First, the PCB <mark>is tested</mark>; then it <mark>is mounted</mark> in the case.</div><div class=\"ts-th\">โมดูลจ่ายไฟประกอบด้วยหม้อแปลง แผงวงจร และกล่องโลหะ กล่องทำจากอะลูมิเนียมและใช้ระบายความร้อน ขั้นแรกแผงวงจรถูกทดสอบ จากนั้นจึงติดตั้งในกล่อง</div></div></div></div>","easy":{"say":"บรรยายชิ้นส่วนด้วยโครงเดิม: made of (วัสดุ) · consists of (ส่วนประกอบ) · is used to (หน้าที่) · mounted on (ตำแหน่ง) · กระบวนการใช้ is/are + V3","eg":["The fuse <b>is used to</b> protect the circuit.","ฟิวส์ใช้ป้องกันวงจร"],"rule":"consist of · made of · used to + V1 · prevent from + V-ing"}},{"id":"qc","en":"Quality control vocabulary","th":"คำศัพท์งานควบคุมคุณภาพ (QC)","intro":"งานคุณภาพมีคำศัพท์เฉพาะที่ใช้ทั่วโลก รู้ความหมายที่ถูกต้องจะสื่อสารกับลูกค้าและผู้จัดหาได้ตรงกัน","r":[],"tips":[],"items":[{"id":"wk-qc-0","p":0,"s":"การตรวจวัตถุดิบตอนรับเข้าโรงงานเรียกว่าอะไร?","gap":0,"o":{"A":"outgoing inspection","B":"incoming inspection (IQC)","C":"final assembly","D":"rework"},"oth":{},"a":"B","x":"incoming = ขาเข้า","v":[]},{"id":"wk-qc-1","p":0,"s":"ชิ้นงานที่ทำใหม่จนได้ตาม spec เรียกว่าอะไร?","gap":0,"o":{"A":"scrap","B":"reject","C":"defect","D":"rework"},"oth":{},"a":"D","x":"rework = ทำใหม่ให้ตรง spec","v":[]},{"id":"wk-qc-2","p":0,"s":"ชิ้นงานที่ทิ้งเพราะแก้ไม่ได้เรียกว่าอะไร?","gap":0,"o":{"A":"yield","B":"sample","C":"rework","D":"scrap"},"oth":{},"a":"D","x":"scrap = เศษ / ของทิ้ง","v":[]},{"id":"wk-qc-3","p":0,"s":"ถ้าผลิต 1,000 ชิ้น ดี 950 ชิ้น yield เท่ากับเท่าไร?","gap":0,"o":{"A":"5%","B":"50%","C":"95%","D":"950 ppm"},"oth":{},"a":"C","x":"950/1,000 = 95%","v":[]},{"id":"wk-qc-4","p":0,"s":"\"defect\" กับ \"defective\" ต่างกันอย่างไร?","gap":0,"o":{"A":"defective = ดี","B":"defect = จุดบกพร่อง (n.) / defective = ที่มีจุดบกพร่อง (adj.)","C":"เหมือนกัน","D":"defect = adj. / defective = n."},"oth":{},"a":"B","x":"ชิ้นหนึ่งอาจมีหลาย defect","v":[]},{"id":"wk-qc-5","p":0,"s":"AQL ในการสุ่มตัวอย่างย่อมาจากอะไร?","gap":0,"o":{"A":"automatic quality line","B":"all quality list","C":"acceptance quality limit","D":"average quantity level"},"oth":{},"a":"C","x":"ISO 2859-1 ใช้ acceptance quality limit (เดิมเรียก acceptable quality level)","v":[]},{"id":"wk-qc-6","p":0,"s":"The lot was _____ because 5 samples failed.","gap":1,"o":{"A":"yielded","B":"reworked to","C":"accepted","D":"rejected"},"oth":{},"a":"D","x":"reject = ไม่รับ","v":[]},{"id":"wk-qc-7","p":0,"s":"\"first pass yield\" หมายถึงอะไร?","gap":0,"o":{"A":"ของเสียครั้งแรก","B":"ผลผลิตวันแรก","C":"สัดส่วนชิ้นงานที่ผ่านครั้งแรกโดยไม่ต้องแก้","D":"ชิ้นแรกที่ผลิต"},"oth":{},"a":"C","x":"FPY ไม่นับชิ้นที่ต้อง rework","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">งานคุณภาพเหมือน <b>ด่านตรวจ</b> สามด่าน: ขาเข้า (IQC) ระหว่างทาง (IPQC) และขาออก (OQC) ของที่ไม่ผ่านด่านต้องตัดสินว่าจะ ทำใหม่ (rework) ซ่อม (repair) ทิ้ง (scrap) หรือส่งคืน (RTV)</div><figure class=\"bv bv-steps\"><ol><li>IQC: incoming inspection (วัตถุดิบเข้า)</li><li>IPQC: in-process inspection (ระหว่างผลิต)</li><li>OQC: outgoing / final inspection (ก่อนส่ง)</li><li>ไม่ผ่าน → nonconformity → disposition</li></ol><figcaption>ด่านตรวจสามด่าน</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>disposition</th><th>ความหมาย</th><th>ต้องอนุมัติ</th></tr></thead><tbody><tr><td>rework</td><td>ทำใหม่ให้ตรง spec เดิม</td><td>ตาม WI</td></tr><tr><td>repair</td><td>ซ่อมให้ใช้งานได้ อาจไม่ตรง spec เดิม</td><td>ใช่ (มักต้องลูกค้าอนุมัติ)</td></tr><tr><td>use as is</td><td>ใช้ตามสภาพ</td><td>ใช่</td></tr><tr><td>scrap</td><td>ทิ้ง</td><td>ตามขั้นตอน</td></tr><tr><td>RTV</td><td>ส่งคืนผู้จัดหา</td><td>ตามขั้นตอน</td></tr></tbody></table></div><figcaption>การตัดสินใจกับของที่ไม่เป็นไปตามข้อกำหนด</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">yield</div><div class=\"tf-value\">ชิ้นดี ÷ ชิ้นทั้งหมด × 100%</div></div><div class=\"tense-formula\"><div class=\"tf-label\">defect rate (ppm)</div><div class=\"tf-value\">ชิ้นเสีย ÷ ชิ้นทั้งหมด × 1,000,000</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ผลการตรวจ</div><div class=\"tf-value\">accept / reject · pass / fail</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>การตรวจ</b> — inspection: incoming (IQC, ตรวจรับ), in-process (IPQC), outgoing / final (OQC) · visual inspection · sampling (สุ่มตัวอย่าง) · 100% inspection</p><p><b>ผลการตรวจ</b> — accept / reject · pass / fail · defect (จุดบกพร่อง) · defective (ชิ้นที่มีจุดบกพร่อง) · nonconformity (ไม่เป็นไปตามข้อกำหนด)</p><p><b>การจัดการของเสีย</b> — rework (ทำใหม่ให้ได้ตาม spec) · repair (ซ่อมให้ใช้ได้ อาจไม่ตรง spec เดิม) · scrap (ทิ้ง) · use as is (ใช้ตามสภาพเมื่อได้รับอนุมัติ) · return to vendor (RTV)</p><p><b>ตัวชี้วัด</b> — yield (ผลได้) · first pass yield (FPY) · defect rate · ppm · AQL (acceptance quality limit) · Cpk (ความสามารถของกระบวนการ)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The lot passed incoming inspection.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The lot passed incoming inspection.</div><div class=\"ex-th thai\">ล็อตนี้ผ่านการตรวจรับ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Twelve units need rework.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Twelve units need rework.</div><div class=\"ex-th thai\">สิบสองเครื่องต้องทำใหม่</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"First pass yield improved to 97%.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">First pass yield improved to 97%.</div><div class=\"ex-th thai\">อัตราผ่านครั้งแรกดีขึ้นเป็น 97%</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The defective parts were scrapped.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The defective parts were scrapped.</div><div class=\"ex-th thai\">ชิ้นส่วนที่บกพร่องถูกทิ้ง</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ The part has many defectives.</p><p class=\"ok\">✓ The part has many defects.</p><small>defect = n. / defective = adj.</small></div><div class=\"bv-m\"><p class=\"no\">✗ rework = repair</p><p class=\"ok\">✓ rework ทำให้ตรง spec / repair แค่ใช้งานได้</p><small>ต่างกันในเอกสารคุณภาพ ต้องใช้ให้ถูก</small></div><div class=\"bv-m\"><p class=\"no\">✗ NG 3 pcs (ไม่มีรายละเอียด)</p><p class=\"ok\">✓ 3 pcs rejected for missing screws</p><small>บอกเหตุผลของการไม่ผ่าน</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำว่า &quot;NG&quot; (no good) ใช้กันในโรงงานเอเชีย แต่ในเอกสารถึงลูกค้าต่างประเทศควรใช้ reject / nonconforming / fail และบอกสาเหตุ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"During incoming inspection, 3 of 80 samples were defective. The lot was rejected and returned to the vendor. Our first pass yield stayed at 98%.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">During <mark>incoming inspection</mark>, 3 of 80 <mark>samples</mark> were <mark>defective</mark>. The lot was <mark>rejected</mark> and returned to the vendor. Our <mark>first pass yield</mark> stayed at 98%.</div><div class=\"ts-th\">ระหว่างการตรวจรับ ตัวอย่าง 3 จาก 80 ชิ้นบกพร่อง ล็อตจึงถูกปฏิเสธและส่งคืนผู้จัดหา อัตราผ่านครั้งแรกของเรายังคงอยู่ที่ 98%</div></div></div></div>","easy":{"say":"งานคุณภาพคือด่านตรวจ 3 ด่าน (IQC, IPQC, OQC) ของไม่ผ่านต้องตัดสิน: rework / repair / use as is / scrap / RTV","eg":["3 of 80 samples were <b>defective</b>; the lot was <b>rejected</b>.","ตัวอย่าง 3 ใน 80 บกพร่อง ล็อตถูกปฏิเสธ"],"rule":"defect (n.) · defective (adj.) · rework ≠ repair"}},{"id":"ncr","en":"Writing a nonconformance report (NCR)","th":"เขียนรายงานของไม่เป็นไปตามข้อกำหนด (NCR)","intro":"NCR ที่ดีบอกปัญหาได้ครบโดยไม่ต้องถามเพิ่ม: อะไร ที่ไหน เมื่อไร เท่าไร ข้อกำหนดคืออะไร พบจริงเท่าไร และจัดการอย่างไร","r":[],"tips":[],"items":[{"id":"wk-ncr-0","p":0,"s":"NCR ย่อมาจากอะไร?","gap":0,"o":{"A":"no change required","B":"nonconformance report","C":"net cost report","D":"new customer request"},"oth":{},"a":"B","x":"รายงานของไม่เป็นไปตามข้อกำหนด","v":[]},{"id":"wk-ncr-1","p":0,"s":"ข้อใดเป็นคำบรรยายปัญหาที่ดีที่สุด?","gap":0,"o":{"A":"On 12 May, IQC found 6 of 50 samples with a hole diameter of 3.4 mm (spec 3.0 ± 0.1 mm).","B":"Some parts are wrong size.","C":"The supplier did a bad job again.","D":"Bad holes."},"oth":{},"a":"A","x":"มีวันที่ จำนวน ค่าที่พบ และข้อกำหนด","v":[]},{"id":"wk-ncr-2","p":0,"s":"Three units were _____ with a missing label.","gap":1,"o":{"A":"find","B":"found","C":"finding","D":"founded"},"oth":{},"a":"B","x":"were found = ถูกพบ (passive)","v":[]},{"id":"wk-ncr-3","p":0,"s":"การแยกและกักของที่สงสัยไว้ทันทีเรียกว่าอะไร?","gap":0,"o":{"A":"disposition","B":"calibration","C":"containment","D":"root cause"},"oth":{},"a":"C","x":"containment = การควบคุมไม่ให้ของเสียหลุดออกไป","v":[]},{"id":"wk-ncr-4","p":0,"s":"\"quarantine the stock\" หมายถึงอะไร?","gap":0,"o":{"A":"ทิ้งของ","B":"ส่งของให้ลูกค้า","C":"กักของไว้ไม่ให้ใช้","D":"นับของ"},"oth":{},"a":"C","x":"quarantine = กักกัน","v":[]},{"id":"wk-ncr-5","p":0,"s":"ส่วน \"Requirement vs Actual\" มีไว้เพื่ออะไร?","gap":0,"o":{"A":"บอกชื่อลูกค้า","B":"ไม่จำเป็น","C":"ให้เห็นว่าข้อกำหนดคืออะไรและต่างจากที่พบเท่าไร","D":"บอกราคา"},"oth":{},"a":"C","x":"ผู้อ่านตัดสินใจได้ทันที","v":[]},{"id":"wk-ncr-6","p":0,"s":"ประโยคใดเป็นภาษาที่เป็นกลาง?","gap":0,"o":{"A":"Your team always fails.","B":"The label is missing on 4 boxes.","C":"The careless operator forgot labels.","D":"Someone was lazy."},"oth":{},"a":"B","x":"บอกข้อเท็จจริง ไม่ใช่ความเห็น","v":[]},{"id":"wk-ncr-7","p":0,"s":"How many ใน 5W2H หมายถึงอะไร?","gap":0,"o":{"A":"จำนวนวันหยุด","B":"จำนวนคนในทีม","C":"จำนวนชิ้นที่มีปัญหาและจำนวนที่ตรวจ","D":"ราคา"},"oth":{},"a":"C","x":"เช่น 6 of 50 pcs","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">NCR เหมือน <b>บันทึกเกิดเหตุของตำรวจ</b>: เขียนเฉพาะสิ่งที่เห็นและวัดได้ ใคร อะไร ที่ไหน เมื่อไร เท่าไร ไม่ใส่ความเห็นหรือกล่าวหา คนที่อ่านทีหลังต้องเข้าใจเหตุการณ์ได้ทั้งหมดจากเอกสาร</div><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">NCR-2026-0412</div><div class=\"wd-r\"><span class=\"wd-l\">Part / Lot</span><div class=\"wd-t\" lang=\"en\">Bracket BR-77, lot 2605-12, supplier: XYZ Co.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Found at / Date / By</span><div class=\"wd-t\" lang=\"en\">Incoming inspection (IQC), 12 May 2026, inspector: K. Suda</div></div><div class=\"wd-r\"><span class=\"wd-l\">Description</span><div class=\"wd-t\" lang=\"en\">6 of 50 samples have a hole diameter out of tolerance.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Requirement vs Actual</span><div class=\"wd-t\" lang=\"en\">Requirement: Ø3.0 ± 0.1 mm / Actual: Ø3.3–3.4 mm</div></div><div class=\"wd-r\"><span class=\"wd-l\">Containment</span><div class=\"wd-t\" lang=\"en\">Lot 2605-12 (2,000 pcs) quarantined. Stock in line checked: 0 pcs affected.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Disposition</span><div class=\"wd-t\" lang=\"en\">Return to vendor (RTV). Supplier to submit an 8D report by 22 May.</div></div></div><figcaption>NCR ที่ครบถ้วน</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>5W2H</th><th>คำถาม</th><th>ตัวอย่าง</th></tr></thead><tbody><tr><td>What</td><td>ปัญหาคืออะไร</td><td>hole diameter out of tolerance</td></tr><tr><td>Where</td><td>พบที่ไหน</td><td>IQC</td></tr><tr><td>When</td><td>เมื่อไร</td><td>12 May 2026</td></tr><tr><td>Who</td><td>ใครพบ</td><td>K. Suda</td></tr><tr><td>Why</td><td>ทำไมเป็นปัญหา</td><td>screw cannot fit</td></tr><tr><td>How</td><td>พบอย่างไร</td><td>pin gauge check</td></tr><tr><td>How many</td><td>จำนวน</td><td>6 of 50 samples</td></tr></tbody></table></div><figcaption>5W2H ช่วยไม่ให้ลืมข้อมูล</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">บรรยาย</div><div class=\"tf-value\">X of Y + noun + were found with ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">เทียบ</div><div class=\"tf-value\">Requirement: ... / Actual: ...</div></div><div class=\"tense-formula\"><div class=\"tf-label\">จัดการ</div><div class=\"tf-value\">containment → disposition</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>5W2H</b> — What (อะไร), Where (ที่ไหน), When (เมื่อไร), Who (ใครพบ), Why (ทำไมเป็นปัญหา), How (พบอย่างไร), How many (จำนวน)</p><p><b>ข้อกำหนด vs ที่พบจริง</b> — Requirement: 10.0 ± 0.1 mm / Actual: 10.4 mm เขียนเทียบกันให้เห็นชัด</p><p><b>ภาษาเป็นกลางและเป็นข้อเท็จจริง</b> — ใช้ was found / was measured / is missing ไม่ใช้ความเห็นหรือกล่าวโทษ<br><span class=\"bv-rx\">Three units were found with a missing screw. <small>พบสามเครื่องขาดสกรู</small></span></p><p><b>containment และ disposition</b> — containment = ควบคุมของที่สงสัยทันที (กักกัน คัดแยก) · disposition = ตัดสินใจกับของเสีย<br><span class=\"bv-rx\">All stock was quarantined and 100% sorted. <small>กักกันของทั้งหมดและคัดแยก 100%</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The parts were measured with a pin gauge.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The parts were measured with a pin gauge.</div><div class=\"ex-th thai\">ชิ้นส่วนถูกวัดด้วยพินเกจ</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The suspect lot was quarantined.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The suspect lot was quarantined.</div><div class=\"ex-th thai\">ล็อตที่สงสัยถูกกักไว้</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"No affected parts were found in the line.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">No affected parts were found in the line.</div><div class=\"ex-th thai\">ไม่พบชิ้นที่ได้รับผลกระทบในไลน์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The supplier shall submit an 8D report.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The supplier shall submit an 8D report.</div><div class=\"ex-th thai\">ผู้จัดหาต้องส่งรายงาน 8D</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Many holes big.</p><p class=\"ok\">✓ 6 of 50 samples: Ø3.3–3.4 mm (spec Ø3.0 ± 0.1 mm)</p><small>ต้องมีจำนวน ค่าที่วัด และข้อกำหนด</small></div><div class=\"bv-m\"><p class=\"no\">✗ The supplier is careless.</p><p class=\"ok\">✓ The hole diameter is out of tolerance.</p><small>NCR บอกข้อเท็จจริง ไม่ใช่ความเห็น</small></div><div class=\"bv-m\"><p class=\"no\">✗ ไม่เขียน containment</p><p class=\"ok\">✓ Containment: lot quarantined, line stock checked</p><small>ลูกค้าต้องรู้ว่าของเสียไม่หลุดออกไปแล้ว</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> แนบรูปถ่ายที่มีไม้บรรทัดหรือป้ายหมายเลขล็อตในภาพเสมอ รูปเดียวช่วยลดอีเมลถามกลับได้หลายฉบับ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"On 12 May, IQC found 6 of 50 samples out of tolerance. Requirement: Ø3.0 ± 0.1 mm; actual: Ø3.3 mm. The lot was quarantined, and the disposition is RTV.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">On 12 May, IQC <mark>found</mark> 6 of 50 samples <mark>out of tolerance</mark>. <mark>Requirement</mark>: Ø3.0 ± 0.1 mm; <mark>actual</mark>: Ø3.3 mm. The lot <mark>was quarantined</mark>, and the <mark>disposition</mark> is RTV.</div><div class=\"ts-th\">วันที่ 12 พฤษภาคม IQC พบตัวอย่าง 6 จาก 50 ชิ้นเกินค่าเผื่อ ข้อกำหนด Ø3.0 ± 0.1 มม. ที่พบ Ø3.3 มม. ล็อตถูกกักไว้ และตัดสินให้ส่งคืนผู้จัดหา</div></div></div></div>","easy":{"say":"NCR คือบันทึกเกิดเหตุ: เขียนเฉพาะข้อเท็จจริงตาม 5W2H เทียบข้อกำหนดกับที่พบจริง แล้วบอก containment และ disposition","eg":["6 of 50 samples <b>were found</b> out of tolerance (spec Ø3.0 ± 0.1 mm).",""],"rule":"5W2H · Requirement vs Actual · containment · disposition"}},{"id":"8d","en":"8D problem solving and CAPA","th":"การแก้ปัญหาแบบ 8D และ CAPA","intro":"8D (Eight Disciplines) คือวิธีแก้ปัญหาคุณภาพ 8 ขั้นที่ลูกค้าทั่วโลกใช้ แต่ละขั้นมีคำศัพท์เฉพาะ และต้องแยก \"แก้ชั่วคราว\" กับ \"แก้ถาวร\" ให้ชัด","r":[],"tips":[],"items":[{"id":"wk-8d-0","p":0,"s":"ขั้นใดของ 8D คือการควบคุมชั่วคราวไม่ให้ของเสียถึงลูกค้า?","gap":0,"o":{"A":"D3 interim containment","B":"D7 prevent recurrence","C":"D4 root cause","D":"D8 recognize the team"},"oth":{},"a":"A","x":"D3 = interim containment action","v":[]},{"id":"wk-8d-1","p":0,"s":"เทคนิคถาม \"ทำไม\" ซ้ำหลายครั้งเพื่อหาสาเหตุรากเรียกว่าอะไร?","gap":0,"o":{"A":"Kanban","B":"Six Sigma","C":"5S","D":"5 Why"},"oth":{},"a":"D","x":"5 Why = ถามทำไมซ้ำจนถึงสาเหตุราก","v":[]},{"id":"wk-8d-2","p":0,"s":"แผนภาพก้างปลาที่ใช้หาสาเหตุเรียกว่าอะไร?","gap":0,"o":{"A":"fishbone (Ishikawa) diagram","B":"Gantt chart","C":"pie chart","D":"flowchart only"},"oth":{},"a":"A","x":"แบ่งสาเหตุเป็นหมวด เช่น Man, Machine, Method, Material","v":[]},{"id":"wk-8d-3","p":0,"s":"corrective action กับ preventive action ต่างกันอย่างไร?","gap":0,"o":{"A":"corrective ป้องกัน / preventive แก้","B":"เหมือนกัน","C":"ทั้งสองคือการซ่อมเครื่อง","D":"corrective แก้ปัญหาที่เกิดแล้ว / preventive ป้องกันก่อนเกิด"},"oth":{},"a":"D","x":"CAPA = Corrective And Preventive Action","v":[]},{"id":"wk-8d-4","p":0,"s":"\"escape point\" ใน D4 หมายถึงอะไร?","gap":0,"o":{"A":"จุดที่ควรตรวจพบปัญหาแต่ไม่พบ","B":"จุดส่งของ","C":"จุดที่ผลิตชิ้นงาน","D":"ทางหนีไฟ"},"oth":{},"a":"A","x":"ต้องแก้ทั้งสาเหตุที่เกิดและสาเหตุที่หลุดรอด","v":[]},{"id":"wk-8d-5","p":0,"s":"D2 ใช้เครื่องมือใดบรรยายปัญหา?","gap":0,"o":{"A":"คำขอโทษ","B":"Gantt chart","C":"ใบเสนอราคา","D":"5W2H / Is–Is not"},"oth":{},"a":"D","x":"บรรยายปัญหาให้ชัดก่อนหาสาเหตุ","v":[]},{"id":"wk-8d-6","p":0,"s":"การ \"validate\" ใน D6 หมายถึงอะไร?","gap":0,"o":{"A":"ยืนยันด้วยข้อมูลว่าการแก้ไขได้ผลจริง","B":"เขียนรายงาน","C":"ส่งของ","D":"ประชุมทีม"},"oth":{},"a":"A","x":"ต้องมีข้อมูลหลังแก้ เช่น ของเสียเป็นศูนย์ 3 ล็อตติด","v":[]},{"id":"wk-8d-7","p":0,"s":"ขั้น D7 มักปรับเอกสารใด?","gap":0,"o":{"A":"ใบเสร็จ","B":"FMEA, control plan, work instruction","C":"ใบลา","D":"สัญญาเช่า"},"oth":{},"a":"B","x":"ป้องกันการเกิดซ้ำในระดับระบบ","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">8D เหมือน <b>การรักษาโรคที่โรงพยาบาล</b>: รวมทีมแพทย์ (D1) ซักประวัติอาการ (D2) ห้ามเลือดก่อน (D3 แก้ชั่วคราว) หาสาเหตุจริง (D4) เลือกการรักษา (D5) รักษาและตรวจซ้ำ (D6) ป้องกันไม่ให้ป่วยอีก (D7) และขอบคุณทีม (D8)</div><figure class=\"bv bv-steps\"><ol><li>D1 Form the team</li><li>D2 Describe the problem (5W2H, Is / Is not)</li><li>D3 Interim containment action</li><li>D4 Root cause (occurrence + escape) — 5 Why, fishbone</li><li>D5 Choose and verify permanent corrective actions</li><li>D6 Implement and validate</li><li>D7 Prevent recurrence (FMEA, control plan, WI)</li><li>D8 Recognize the team</li></ol><figcaption>ขั้นตอน 8D (Ford 8D)</figcaption></figure><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>Why?</th><th>Because ...</th></tr></thead><tbody><tr><td>1. Why was the screw missing?</td><td>The screwdriver did not pick up a screw.</td></tr><tr><td>2. Why did it not pick up a screw?</td><td>The feeder was empty.</td></tr><tr><td>3. Why was the feeder empty?</td><td>Nobody refilled it on time.</td></tr><tr><td>4. Why was it not refilled?</td><td>There was no low-level alarm.</td></tr><tr><td>5. Root cause</td><td>The feeder has no low-level sensor. → Action: add a sensor and an alarm.</td></tr></tbody></table></div><figcaption>ตัวอย่าง 5 Why ถามจนถึงสาเหตุที่แก้ได้ในระบบ</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">ชั่วคราว</div><div class=\"tf-value\">D3 containment: sort, quarantine</div></div><div class=\"tense-formula\"><div class=\"tf-label\">สาเหตุ</div><div class=\"tf-value\">D4: occurrence + escape</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ถาวร + ป้องกัน</div><div class=\"tf-value\">D5–D7: corrective + preventive</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>D1–D3</b> — D1 Form the team (ตั้งทีม) · D2 Describe the problem (บรรยายปัญหา 5W2H) · D3 Interim containment action (การควบคุมชั่วคราว)</p><p><b>D4: root cause</b> — หาสาเหตุราก ทั้งสาเหตุที่เกิด (occurrence) และสาเหตุที่หลุดถึงลูกค้า (escape) ด้วย 5 Why หรือ fishbone (Ishikawa)<br><span class=\"bv-rx\">Why was the screw missing? Because the feeder was empty... <small>ทำไมสกรูหาย เพราะเครื่องป้อนสกรูหมด...</small></span></p><p><b>D5–D6</b> — D5 Choose and verify permanent corrective actions (เลือกและพิสูจน์การแก้ถาวร) · D6 Implement and validate (นำไปใช้และยืนยันผล)</p><p><b>D7–D8 และ CAPA</b> — D7 Prevent recurrence (ป้องกันการเกิดซ้ำ ปรับระบบ เช่น FMEA, control plan) · D8 Recognize the team · CAPA = corrective action (แก้ที่เกิดแล้ว) + preventive action (ป้องกันก่อนเกิด)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Interim containment: 100% visual check at OQC.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Interim containment: 100% visual check at OQC.</div><div class=\"ex-th thai\">การควบคุมชั่วคราว: ตรวจด้วยตา 100% ที่ OQC</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The root cause was a worn cutting blade.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The root cause was a worn cutting blade.</div><div class=\"ex-th thai\">สาเหตุรากคือใบมีดสึก</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The corrective action was verified on three lots.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The corrective action was verified on three lots.</div><div class=\"ex-th thai\">การแก้ไขได้รับการพิสูจน์ในสามล็อต</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The FMEA was updated to prevent recurrence.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The FMEA was updated to prevent recurrence.</div><div class=\"ex-th thai\">FMEA ได้รับการปรับเพื่อป้องกันการเกิดซ้ำ</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่ลูกค้ามักตีกลับรายงาน 8D</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Root cause: operator mistake.</p><p class=\"ok\">✓ Root cause: the fixture allows the part to be placed backwards.</p><small>ความผิดพลาดของคนมักเป็นอาการ ไม่ใช่สาเหตุราก ให้ถามต่อว่าทำไมระบบเปิดโอกาสให้ผิด</small></div><div class=\"bv-m\"><p class=\"no\">✗ Corrective action: retrain the operator. (อย่างเดียว)</p><p class=\"ok\">✓ Add a poka-yoke pin to the fixture + update the WI.</p><small>การอบรมซ้ำอย่างเดียวไม่ป้องกันการเกิดซ้ำได้จริง</small></div><div class=\"bv-m\"><p class=\"no\">✗ ข้าม D3 ไปหา D4 ก่อน</p><p class=\"ok\">✓ ทำ D3 ทันที</p><small>ต้องหยุดไม่ให้ของเสียถึงลูกค้าก่อน</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> poka-yoke (กันความผิดพลาด) เป็นคำญี่ปุ่นที่ใช้ทั่วโลก หมายถึงอุปกรณ์หรือวิธีที่ทำให้ทำผิดไม่ได้ เช่น หมุดที่ทำให้ใส่ชิ้นงานกลับด้านไม่ได้</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"D3: all stock was sorted. D4: using 5 Why, we found the root cause: the feeder had no low-level alarm. D5–D6: a sensor was added and validated on three lots. D7: the FMEA was updated.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>D3</mark>: all stock was sorted. <mark>D4</mark>: using <mark>5 Why</mark>, we found the <mark>root cause</mark>: the feeder had no low-level alarm. <mark>D5–D6</mark>: a sensor was added and <mark>validated</mark> on three lots. <mark>D7</mark>: the <mark>FMEA</mark> was updated.</div><div class=\"ts-th\">D3 คัดแยกของทั้งหมด D4 ใช้ 5 Why พบสาเหตุรากว่าเครื่องป้อนไม่มีสัญญาณเตือนระดับต่ำ D5–D6 ติดเซนเซอร์และยืนยันผลในสามล็อต D7 ปรับ FMEA</div></div></div></div>","easy":{"say":"8D คือการรักษาโรค 8 ขั้น: หยุดเลือดก่อน (D3 ชั่วคราว) แล้วหาสาเหตุจริง (D4 ด้วย 5 Why) แก้ถาวร ยืนยันผล และป้องกันที่ระบบ","eg":["<b>Root cause</b>: the feeder had no low-level alarm.","สาเหตุราก: เครื่องป้อนไม่มีสัญญาณเตือนระดับต่ำ"],"rule":"containment ≠ corrective action · \"คนผิด\" ไม่ใช่สาเหตุราก"}},{"id":"trouble","en":"Troubleshooting and maintenance","th":"การแก้ไขเหตุขัดข้องและการบำรุงรักษา","intro":"คู่มือ troubleshooting ใช้ตาราง อาการ – สาเหตุที่เป็นไปได้ – วิธีแก้ และประโยคเงื่อนไข If ... เพื่อบอกขั้นตอนตรวจ","r":[],"tips":[],"items":[{"id":"wk-trouble-0","p":0,"s":"If the machine _____, check the emergency stop button.","gap":1,"o":{"A":"will not to start","B":"does not start","C":"not starting","D":"did not started"},"oth":{},"a":"B","x":"If + present simple","v":[]},{"id":"wk-trouble-1","p":0,"s":"ในตาราง troubleshooting \"Remedy\" หมายถึงอะไร?","gap":0,"o":{"A":"ผู้รับผิดชอบ","B":"อาการ","C":"วิธีแก้","D":"สาเหตุ"},"oth":{},"a":"C","x":"remedy = วิธีแก้ไข","v":[]},{"id":"wk-trouble-2","p":0,"s":"The vibration _____ caused by a worn bearing.","gap":1,"o":{"A":"may","B":"maybe is","C":"is may","D":"may be"},"oth":{},"a":"D","x":"may be caused by = อาจเกิดจาก","v":[]},{"id":"wk-trouble-3","p":0,"s":"การบำรุงรักษาตามรอบก่อนเครื่องเสียเรียกว่าอะไร?","gap":0,"o":{"A":"scrap","B":"preventive maintenance","C":"breakdown maintenance","D":"rework"},"oth":{},"a":"B","x":"PM = preventive maintenance","v":[]},{"id":"wk-trouble-4","p":0,"s":"\"Lubricate the chain\" หมายถึงอะไร?","gap":0,"o":{"A":"หล่อลื่นโซ่","B":"เปลี่ยนโซ่","C":"ตัดโซ่","D":"ทำความสะอาดโซ่"},"oth":{},"a":"A","x":"lubricate = หล่อลื่น","v":[]},{"id":"wk-trouble-5","p":0,"s":"ชิ้นส่วนที่บางลงเพราะใช้งานนาน เรียกว่าอะไร?","gap":0,"o":{"A":"lubricated","B":"broken new","C":"calibrated","D":"worn"},"oth":{},"a":"D","x":"worn (V3 ของ wear) = สึก","v":[]},{"id":"wk-trouble-6","p":0,"s":"If the error code E05 _____, replace the filter.","gap":1,"o":{"A":"appears","B":"will appear","C":"appearing","D":"appeared to"},"oth":{},"a":"A","x":"If + present simple","v":[]},{"id":"wk-trouble-7","p":0,"s":"\"The fault is likely due to low air pressure.\" หมายถึงอะไร?","gap":0,"o":{"A":"ความผิดปกติน่าจะเกิดจากแรงดันลมต่ำ","B":"ต้องเพิ่มแรงดันเสมอ","C":"แรงดันลมต่ำแน่นอน","D":"ไม่มีความผิดปกติ"},"oth":{},"a":"A","x":"likely due to = น่าจะเกิดจาก","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">troubleshooting เหมือน <b>หมอวินิจฉัยโรค</b>: เริ่มจากอาการ (symptom) ไล่ดูสาเหตุที่เป็นไปได้จากง่ายไปยาก (possible cause) แล้วรักษา (remedy) ภาษาที่ใช้ระวังไม่ฟันธงเกินไป ใช้ may / likely เมื่อยังไม่แน่ใจ</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>Symptom</th><th>Possible cause</th><th>Remedy</th></tr></thead><tbody><tr><td>The machine does not start.</td><td>Emergency stop is pressed.</td><td>Release the E-stop and press RESET.</td></tr><tr><td>The LED flashes red.</td><td>The fuse is blown.</td><td>Replace the fuse (2 A).</td></tr><tr><td>Loud noise from the motor.</td><td>The belt is loose or worn.</td><td>Adjust or replace the belt.</td></tr><tr><td>Parts are not picked up.</td><td>Low vacuum pressure.</td><td>Check the filter and the hose.</td></tr></tbody></table></div><figcaption>ตาราง troubleshooting ในคู่มือเครื่อง</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>Symptom: บอกอาการที่เห็น</li><li>If ..., check ... (เริ่มจากสิ่งที่ตรวจง่าย)</li><li>Possible cause: may be / is likely due to ...</li><li>Remedy: replace / adjust / clean ...</li><li>If the problem continues, contact ...</li></ol><figcaption>ลำดับการแก้ปัญหา</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เงื่อนไข</div><div class=\"tf-value\">If + present, imperative</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ความเป็นไปได้</div><div class=\"tf-value\">may be caused by / is likely due to</div></div><div class=\"tense-formula\"><div class=\"tf-label\">บำรุงรักษา</div><div class=\"tf-value\">clean · lubricate · adjust · replace · inspect</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>ตาราง troubleshooting</b> — Symptom (อาการ) → Possible cause (สาเหตุที่เป็นไปได้) → Remedy / Action (วิธีแก้)</p><p><b>ประโยคเงื่อนไข</b> — If + present, imperative: If the LED flashes red, check the fuse. · If the problem continues, contact service.</p><p><b>คำบอกความเป็นไปได้</b> — may / might / could be caused by · is likely due to · probably<br><span class=\"bv-rx\">The noise <b>may be caused by</b> a loose belt. <small>เสียงดังอาจเกิดจากสายพานหลวม</small></span></p><p><b>การบำรุงรักษา</b> — preventive maintenance (PM, ตามรอบ) · breakdown / corrective maintenance (เมื่อเสีย) · lubricate, replace, adjust, clean, inspect, wear (สึก)<br><span class=\"bv-rx\">Lubricate the rails every 500 hours. <small>หล่อลื่นรางทุก 500 ชั่วโมง</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"If the alarm sounds, stop the line.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">If the alarm sounds, stop the line.</div><div class=\"ex-th thai\">ถ้าสัญญาณเตือนดัง ให้หยุดไลน์</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The error may be caused by a loose connector.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The error may be caused by a loose connector.</div><div class=\"ex-th thai\">ข้อผิดพลาดอาจเกิดจากคอนเนกเตอร์หลวม</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Replace the filter every three months.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Replace the filter every three months.</div><div class=\"ex-th thai\">เปลี่ยนไส้กรองทุกสามเดือน</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The bearing is worn and must be replaced.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The bearing is worn and must be replaced.</div><div class=\"ex-th thai\">แบริ่งสึกและต้องเปลี่ยน</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ If the machine will stop, call me.</p><p class=\"ok\">✓ If the machine stops, call me.</p><small>หลัง If ใช้ present simple</small></div><div class=\"bv-m\"><p class=\"no\">✗ The noise is caused by the belt. (ยังไม่ได้ตรวจ)</p><p class=\"ok\">✓ The noise may be caused by the belt.</p><small>ยังไม่แน่ใจ ใช้ may</small></div><div class=\"bv-m\"><p class=\"no\">✗ Fix it. (ไม่บอกวิธี)</p><p class=\"ok\">✓ Tighten the belt to 50 N tension.</p><small>remedy ต้องบอกการกระทำที่ชัดเจน</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> คำว่า fault, failure, error, malfunction ใช้ใกล้กัน: fault = ความผิดปกติ · failure = หยุดทำงาน/เสีย · error = ข้อผิดพลาด (มักมีรหัส) · malfunction = ทำงานผิดปกติ</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Symptom: the robot stops after ten cycles. Possible cause: the air pressure may be too low. Remedy: check the regulator. If the problem continues, contact the maintenance team.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\"><mark>Symptom</mark>: the robot stops after ten cycles. <mark>Possible cause</mark>: the air pressure <mark>may be</mark> too low. <mark>Remedy</mark>: check the regulator. <mark>If the problem continues</mark>, contact the maintenance team.</div><div class=\"ts-th\">อาการ: หุ่นยนต์หยุดหลังทำงานสิบรอบ สาเหตุที่เป็นไปได้: แรงดันลมอาจต่ำเกินไป วิธีแก้: ตรวจตัวปรับแรงดัน ถ้ายังมีปัญหา ติดต่อทีมซ่อมบำรุง</div></div></div></div>","easy":{"say":"troubleshooting คือหมอวินิจฉัย: อาการ → สาเหตุที่เป็นไปได้ (may / likely) → วิธีแก้ และใช้ If + present, คำสั่ง","eg":["<b>If</b> the LED <b>flashes</b> red, <b>check</b> the fuse.","ถ้าไฟ LED กะพริบแดง ให้ตรวจฟิวส์"],"rule":"If + present · may be caused by · remedy ต้องชัด"}},{"id":"safety","en":"Safety and ESD","th":"ความปลอดภัยและไฟฟ้าสถิต (ESD)","intro":"ป้ายและกฎความปลอดภัยในโรงงานใช้ภาษาสั้น ชัด และบังคับ คนทำงานอิเล็กทรอนิกส์ต้องรู้คำศัพท์ ESD เป็นพิเศษ","r":[],"tips":[],"items":[{"id":"wk-safety-0","p":0,"s":"ESD ย่อมาจากอะไร?","gap":0,"o":{"A":"emergency stop door","B":"energy saving design","C":"electrostatic discharge","D":"electronic safety device"},"oth":{},"a":"C","x":"การคายประจุไฟฟ้าสถิต","v":[]},{"id":"wk-safety-1","p":0,"s":"Hearing protection _____ be worn when the press is running.","gap":1,"o":{"A":"can","B":"must","C":"might","D":"would"},"oth":{},"a":"B","x":"ข้อบังคับใช้ must","v":[]},{"id":"wk-safety-2","p":0,"s":"PPE หมายถึงอะไร?","gap":0,"o":{"A":"ใบอนุญาตทำงาน","B":"อุปกรณ์ป้องกันส่วนบุคคล","C":"แผนการผลิต","D":"การบำรุงรักษา"},"oth":{},"a":"B","x":"personal protective equipment","v":[]},{"id":"wk-safety-3","p":0,"s":"ป้าย \"No smoking\" มีโครงสร้างใด?","gap":0,"o":{"A":"Don't + noun","B":"No + V-ing","C":"No + V1","D":"Not + V-ing"},"oth":{},"a":"B","x":"No smoking / No parking","v":[]},{"id":"wk-safety-4","p":0,"s":"ก่อนซ่อมเครื่อง ต้องตัดพลังงานและล็อกไว้ เรียกว่าอะไร?","gap":0,"o":{"A":"lockout / tagout (LOTO)","B":"containment","C":"calibration","D":"rework"},"oth":{},"a":"A","x":"LOTO ป้องกันไม่ให้มีคนเปิดเครื่องระหว่างซ่อม","v":[]},{"id":"wk-safety-5","p":0,"s":"พื้นที่ที่ควบคุมไฟฟ้าสถิตเรียกว่าอะไร?","gap":0,"o":{"A":"EPA (ESD protected area)","B":"PM area","C":"OQC","D":"warehouse"},"oth":{},"a":"A","x":"EPA","v":[]},{"id":"wk-safety-6","p":0,"s":"เหตุการณ์ที่เกือบเกิดอุบัติเหตุ แต่ไม่มีใครบาดเจ็บ เรียกว่าอะไร?","gap":0,"o":{"A":"near miss","B":"miss call","C":"safe point","D":"hazard free"},"oth":{},"a":"A","x":"near miss ควรรายงานเพื่อป้องกันอุบัติเหตุจริง","v":[]},{"id":"wk-safety-7","p":0,"s":"Food and drinks are _____ in the clean room.","gap":1,"o":{"A":"prohibition","B":"prohibited","C":"prohibiting","D":"prohibit"},"oth":{},"a":"B","x":"are prohibited = ห้าม (passive)","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">ไฟฟ้าสถิตเหมือน <b>ฟ้าผ่าจิ๋ว</b>: เราอาจไม่รู้สึกเลยที่ต่ำกว่าราว 3,000 โวลต์ แต่ชิปบางตัวเสียได้ที่ไม่กี่ร้อยโวลต์ หรือต่ำกว่านั้น จึงต้องใส่สายรัดข้อมือและทำงานใน EPA ภาษาความปลอดภัยต้องสั้นและบังคับ เพราะไม่มีเวลาตีความ</div><figure class=\"bv bv-table\"><div class=\"bv-tw\"><table><thead><tr><th>ป้าย / ประโยค</th><th>ความหมาย</th></tr></thead><tbody><tr><td>DANGER: High voltage</td><td>อันตราย: ไฟฟ้าแรงสูง</td></tr><tr><td>Safety glasses must be worn.</td><td>ต้องสวมแว่นนิรภัย</td></tr><tr><td>No food or drinks.</td><td>ห้ามอาหารและเครื่องดื่ม</td></tr><tr><td>ESD sensitive device. Handle with care.</td><td>อุปกรณ์ไวต่อไฟฟ้าสถิต จับด้วยความระมัดระวัง</td></tr><tr><td>EPA: wrist strap required</td><td>พื้นที่ควบคุม ESD: ต้องใส่สายรัดข้อมือ</td></tr><tr><td>Lockout before servicing.</td><td>ล็อกพลังงานก่อนซ่อมบำรุง</td></tr></tbody></table></div><figcaption>ป้ายความปลอดภัยที่พบในโรงงาน</figcaption></figure><figure class=\"bv bv-steps\"><ol><li>Put on the ESD smock and shoes.</li><li>Connect the wrist strap to the ground point.</li><li>Test the strap at the tester (PASS).</li><li>Handle boards by the edges only.</li><li>Store boards in ESD bags or trays.</li></ol><figcaption>ขั้นตอนเข้า EPA</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">บังคับ</div><div class=\"tf-value\">must / is required</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ห้าม</div><div class=\"tf-value\">must not / Do not / No + V-ing / is prohibited</div></div><div class=\"tense-formula\"><div class=\"tf-label\">ESD</div><div class=\"tf-value\">wrist strap · grounding · EPA · ESD bag</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>คำบังคับและห้าม</b> — must / must not / Do not / No + V-ing (No smoking) · is prohibited / is required<br><span class=\"bv-rx\">Safety glasses <b>must</b> be worn in this area. <small>ต้องสวมแว่นนิรภัยในพื้นที่นี้</small></span></p><p><b>PPE</b> — personal protective equipment: safety glasses, gloves, ear plugs, safety shoes, helmet, mask</p><p><b>ESD</b> — electrostatic discharge (การคายประจุไฟฟ้าสถิต) · EPA (ESD protected area) · wrist strap · grounding (ต่อลงดิน) · ESD bag / mat / smock<br><span class=\"bv-rx\">Connect your wrist strap before you touch the board. <small>ต่อสายรัดข้อมือก่อนแตะแผงวงจร</small></span></p><p><b>ขั้นตอนความปลอดภัย</b> — lockout / tagout (LOTO, ตัดและล็อกพลังงานก่อนซ่อม) · emergency stop · hazard (อันตราย) · near miss (เกือบเกิดอุบัติเหตุ)</p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Do not enter without a helmet.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Do not enter without a helmet.</div><div class=\"ex-th thai\">ห้ามเข้าโดยไม่สวมหมวกนิรภัย</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Ground yourself before touching the board.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Ground yourself before touching the board.</div><div class=\"ex-th thai\">ต่อตัวลงดินก่อนแตะแผงวงจร</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Report every near miss to your supervisor.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Report every near miss to your supervisor.</div><div class=\"ex-th thai\">รายงานเหตุการณ์เกือบเกิดอุบัติเหตุทุกครั้งต่อหัวหน้า</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Lock out the machine before cleaning.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Lock out the machine before cleaning.</div><div class=\"ex-th thai\">ล็อกพลังงานเครื่องก่อนทำความสะอาด</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ No smoke.</p><p class=\"ok\">✓ No smoking.</p><small>No + V-ing</small></div><div class=\"bv-m\"><p class=\"no\">✗ You should wear glasses. (บังคับจริง)</p><p class=\"ok\">✓ Safety glasses must be worn.</p><small>กฎความปลอดภัยใช้ must</small></div><div class=\"bv-m\"><p class=\"no\">✗ ESD = ไฟดูด</p><p class=\"ok\">✓ ESD = การคายประจุไฟฟ้าสถิต</p><small>ESD มักทำลายชิ้นส่วนอิเล็กทรอนิกส์โดยที่คนไม่รู้สึก</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> ESD มักทำให้ชิ้นส่วนเสียแบบแฝง (latent damage) ผ่านการทดสอบตอนแรกแต่เสียทีหลังที่ลูกค้า จึงต้องป้องกันทุกครั้ง แม้ไม่เห็นผลทันที</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"Before entering the EPA, put on your ESD smock and connect your wrist strap. Safety glasses must be worn at the soldering station. No food or drinks are allowed.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">Before entering the <mark>EPA</mark>, put on your <mark>ESD smock</mark> and <mark>connect</mark> your <mark>wrist strap</mark>. <mark>Safety glasses must be worn</mark> at the soldering station. <mark>No food or drinks</mark> are allowed.</div><div class=\"ts-th\">ก่อนเข้าพื้นที่ควบคุม ESD ให้สวมเสื้อกันไฟฟ้าสถิตและต่อสายรัดข้อมือ ต้องสวมแว่นนิรภัยที่สถานีบัดกรี ห้ามนำอาหารและเครื่องดื่มเข้า</div></div></div></div>","easy":{"say":"ภาษาความปลอดภัยสั้นและบังคับ: must / Do not / No + V-ing และงานอิเล็กทรอนิกส์ต้องรู้ ESD, EPA, wrist strap, grounding","eg":["<b>No</b> smok<b>ing</b>. · Gloves <b>must</b> be worn.","ห้ามสูบบุหรี่ · ต้องสวมถุงมือ"],"rule":"ESD = ไฟฟ้าสถิต ทำลายชิปโดยเราไม่รู้สึก"}},{"id":"change","en":"Engineering changes and documents","th":"การเปลี่ยนแปลงทางวิศวกรรมและเอกสาร","intro":"เอกสารวิศวกรรมมีการควบคุมรุ่น (revision) ทุกการเปลี่ยนแปลงต้องผ่านคำขอ การอนุมัติ และแจ้งทุกฝ่ายด้วยภาษาที่เป็นทางการและชัดเจน","r":[],"tips":[],"items":[{"id":"wk-change-0","p":0,"s":"BOM ย่อมาจากอะไร?","gap":0,"o":{"A":"bill of materials","B":"board of management","C":"basic order method","D":"box of materials"},"oth":{},"a":"A","x":"รายการวัสดุและชิ้นส่วนของผลิตภัณฑ์","v":[]},{"id":"wk-change-1","p":0,"s":"เอกสารขอเปลี่ยนแปลงทางวิศวกรรมเรียกว่าอะไร?","gap":0,"o":{"A":"PO","B":"NCR","C":"CoC","D":"ECR (engineering change request)"},"oth":{},"a":"D","x":"ECR = คำขอ / ECN = ประกาศหลังอนุมัติ","v":[]},{"id":"wk-change-2","p":0,"s":"\"Rev. D supersedes Rev. C\" หมายถึงอะไร?","gap":0,"o":{"A":"ยกเลิกทั้งสอง","B":"ใช้ทั้งสองพร้อมกัน","C":"Rev. D ใช้แทน Rev. C","D":"Rev. C ใช้แทน Rev. D"},"oth":{},"a":"C","x":"supersede = แทนที่","v":[]},{"id":"wk-change-3","p":0,"s":"การขออนุญาตใช้ชิ้นส่วนที่ต่างจาก spec ชั่วคราวเรียกว่าอะไร?","gap":0,"o":{"A":"revision","B":"validation","C":"quotation","D":"deviation"},"oth":{},"a":"D","x":"deviation = การเบี่ยงจากข้อกำหนดชั่วคราวโดยได้รับอนุมัติ","v":[]},{"id":"wk-change-4","p":0,"s":"The capacitor C3 is changed _____ 10 µF _____ 22 µF.","gap":1,"o":{"A":"to / from","B":"from / to","C":"by / with","D":"at / on"},"oth":{},"a":"B","x":"changed from ... to ...","v":[]},{"id":"wk-change-5","p":0,"s":"\"effective date\" หมายถึงอะไร?","gap":0,"o":{"A":"วันหมดอายุ","B":"วันที่เริ่มมีผลบังคับใช้","C":"วันที่เขียนเอกสาร","D":"วันประชุม"},"oth":{},"a":"B","x":"effective = มีผล","v":[]},{"id":"wk-change-6","p":0,"s":"เอกสารที่ \"obsolete\" หมายถึงอะไร?","gap":0,"o":{"A":"ยกเลิกใช้แล้ว","B":"ฉบับร่าง","C":"ฉบับใหม่ล่าสุด","D":"ฉบับอนุมัติ"},"oth":{},"a":"A","x":"obsolete = เลิกใช้","v":[]},{"id":"wk-change-7","p":0,"s":"ในใบแจ้งการเปลี่ยนแปลง ส่วน \"Impact\" บอกอะไร?","gap":0,"o":{"A":"ราคาขาย","B":"สีของเอกสาร","C":"ผลกระทบต่อการผลิต ต้นทุน สต็อก และลูกค้า","D":"ชื่อผู้เขียน"},"oth":{},"a":"C","x":"ทุกฝ่ายต้องรู้ว่าการเปลี่ยนกระทบอะไร","v":[]}],"grp":"Technical English — ภาษาอังกฤษเทคนิค","html":"<div class=\"tense-detail-card open bv-page\"><div class=\"tense-detail-body\"><div class=\"bv-hook\">เอกสารวิศวกรรมเหมือน <b>แผนที่ฉบับล่าสุด</b>: ถ้าคนหนึ่งใช้แผนที่เก่า (Rev. B) อีกคนใช้ฉบับใหม่ (Rev. C) ทีมจะเดินคนละทาง การเปลี่ยนแปลงจึงต้องมีคำขอ (ECR) การอนุมัติ ประกาศ (ECN) และวันที่มีผลชัดเจน</div><figure class=\"bv bv-steps\"><ol><li>ECR: engineering change request (ใครขอ ขออะไร ทำไม)</li><li>Review: engineering, quality, production, purchasing</li><li>Approval: approved / rejected</li><li>ECN: notice to all departments + effective date</li><li>Update: drawing, BOM, WI, control plan (Rev. +1)</li><li>Implement + verify first lot</li></ol><figcaption>วงจรการเปลี่ยนแปลงทางวิศวกรรม</figcaption></figure><figure class=\"bv bv-doc\"><div class=\"wd\"><div class=\"wd-h\" lang=\"en\">ECN-2026-031 (effective 1 June 2026)</div><div class=\"wd-r\"><span class=\"wd-l\">Change</span><div class=\"wd-t\" lang=\"en\">R12 is changed from 10 kΩ to 12 kΩ (BOM rev. F → G).</div></div><div class=\"wd-r\"><span class=\"wd-l\">Reason</span><div class=\"wd-t\" lang=\"en\">To reduce LED current to 15 mA and extend LED life.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Impact</span><div class=\"wd-t\" lang=\"en\">Old stock of 10 kΩ (5,000 pcs) to be used on model A only. No change to the PCB.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Documents</span><div class=\"wd-t\" lang=\"en\">Drawing D-4410 Rev. D supersedes Rev. C. WI-ASSY-014 updated.</div></div><div class=\"wd-r\"><span class=\"wd-l\">Approved by</span><div class=\"wd-t\" lang=\"en\">Engineering, QA, Production</div></div></div><figcaption>ตัวอย่างใบประกาศการเปลี่ยนแปลง</figcaption></figure><div class=\"tense-formula-grid\"><div class=\"tense-formula\"><div class=\"tf-label\">เปลี่ยน</div><div class=\"tf-value\">X is changed from A to B.</div></div><div class=\"tense-formula\"><div class=\"tf-label\">รุ่น</div><div class=\"tf-value\">Rev. D supersedes Rev. C.</div></div><div class=\"tense-formula\"><div class=\"tf-label\">มีผล</div><div class=\"tf-value\">effective from + date</div></div></div><h3 class=\"bv-h\">หลักการ</h3><div class=\"tense-usage\"><p><b>เอกสารหลัก</b> — drawing (แบบ) · BOM (bill of materials, รายการวัสดุ) · specification · work instruction · control plan · FMEA</p><p><b>การเปลี่ยนแปลง</b> — ECR = engineering change request (คำขอ) · ECN / ECO = engineering change notice / order (ประกาศ / คำสั่งเปลี่ยน) · deviation (ขออนุญาตใช้ต่างจาก spec ชั่วคราว)</p><p><b>รุ่นของเอกสาร</b> — Rev. A → Rev. B · supersedes (ใช้แทน) · effective date (วันที่มีผล) · obsolete (ยกเลิกใช้)<br><span class=\"bv-rx\">Rev. C supersedes Rev. B from 1 June. <small>Rev. C ใช้แทน Rev. B ตั้งแต่ 1 มิถุนายน</small></span></p><p><b>ภาษาทางการในการแจ้ง</b> — is changed from ... to ... · Reason for change: ... · Impact: ... · Approved by: ...<br><span class=\"bv-rx\">The resistor R12 is changed from 10 kΩ to 12 kΩ. <small>ตัวต้านทาน R12 เปลี่ยนจาก 10 kΩ เป็น 12 kΩ</small></span></p></div><h3 class=\"bv-h\">ตัวอย่างประโยค</h3><div class=\"tense-examples\"><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"Please use the latest revision of the drawing.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">Please use the latest revision of the drawing.</div><div class=\"ex-th thai\">กรุณาใช้แบบฉบับแก้ไขล่าสุด</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The old BOM is now obsolete.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The old BOM is now obsolete.</div><div class=\"ex-th thai\">BOM เก่ายกเลิกใช้แล้ว</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"The change is effective from lot 2606-01.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">The change is effective from lot 2606-01.</div><div class=\"ex-th thai\">การเปลี่ยนมีผลตั้งแต่ล็อต 2606-01</div></div></div><div class=\"tense-example bv-exr\"><button class=\"icon-btn bv-say\" data-say=\"A deviation was approved for 500 pcs.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button><div><div class=\"ex-en\">A deviation was approved for 500 pcs.</div><div class=\"ex-th thai\">การขอใช้ต่างจากข้อกำหนดได้รับอนุมัติสำหรับ 500 ชิ้น</div></div></div></div><h3 class=\"bv-h\">ข้อผิดพลาดที่คนไทยทำบ่อย</h3><div class=\"bv-mis\"><div class=\"bv-m\"><p class=\"no\">✗ Change R12 10k to 12k.</p><p class=\"ok\">✓ R12 is changed from 10 kΩ to 12 kΩ.</p><small>ใช้ from ... to ... และหน่วยเต็ม</small></div><div class=\"bv-m\"><p class=\"no\">✗ ไม่ระบุวันที่มีผล</p><p class=\"ok\">✓ Effective date: 1 June 2026 / from lot 2606-01</p><small>ไม่รู้ว่าเริ่มใช้เมื่อไร = ผลิตผิดได้</small></div><div class=\"bv-m\"><p class=\"no\">✗ ใช้ deviation แทนการแก้แบบถาวร</p><p class=\"ok\">✓ deviation ใช้ชั่วคราวและจำกัดจำนวน</p><small>ถ้าเปลี่ยนถาวรต้องทำ ECR / ECN</small></div></div><div class=\"tense-tip\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 18h6M10 21h4M12 3a6 6 0 0 0-3.5 10.9c.5.36.5 1 .5 1.6h6c0-.6 0-1.24.5-1.6A6 6 0 0 0 12 3z\"/></svg><p><b>เกร็ดความรู้:</b> พิมพ์เอกสารใช้ในไลน์ให้มี &quot;Rev.&quot; และ &quot;Effective date&quot; ที่หัวกระดาษเสมอ และเก็บฉบับเก่าออกจากไลน์ทันทีที่มีฉบับใหม่ (มีป้าย OBSOLETE)</p></div><div class=\"tense-story\"><div class=\"ts-label\">ตัวอย่างเนื้อเรื่อง <button class=\"icon-btn bv-say\" data-say=\"The ECR was approved on 20 May. ECN-031 says R12 is changed from 10 kΩ to 12 kΩ, effective 1 June. Drawing Rev. D supersedes Rev. C.\" aria-label=\"ฟัง\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M4 9v6h4l5 4V5L8 9H4z\"/><path d=\"M16 8.5a5 5 0 0 1 0 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></button></div><div class=\"ts-en\">The <mark>ECR</mark> was <mark>approved</mark> on 20 May. <mark>ECN-031</mark> says R12 <mark>is changed from</mark> 10 kΩ <mark>to</mark> 12 kΩ, <mark>effective</mark> 1 June. Drawing Rev. D <mark>supersedes</mark> Rev. C.</div><div class=\"ts-th\">คำขอเปลี่ยนแปลงได้รับอนุมัติวันที่ 20 พฤษภาคม ECN-031 ระบุว่า R12 เปลี่ยนจาก 10 kΩ เป็น 12 kΩ มีผลวันที่ 1 มิถุนายน แบบ Rev. D ใช้แทน Rev. C</div></div></div></div>","easy":{"say":"เอกสารวิศวกรรมคือแผนที่ฉบับล่าสุด: เปลี่ยนต้องมี ECR (ขอ) → อนุมัติ → ECN (ประกาศ) + วันที่มีผล + Rev. ใหม่","eg":["R12 <b>is changed from</b> 10 kΩ <b>to</b> 12 kΩ, <b>effective</b> 1 June.",""],"rule":"ECR ขอ · ECN ประกาศ · supersedes แทนที่ · obsolete เลิกใช้"}}]};
